pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: post_residual near 0 is good.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize dead space that can't fit the next item (lookahead coupling).
    if next_item_size > 0 {
        if post_residual > 0 && post_residual < next_item_size {
            score += 6.0 * (next_item_size - post_residual) as f64;
        } else if post_residual >= next_item_size && post_residual > 0 {
            // Reward leaving space exactly usable by next item.
            score -= 4.0 * (next_item_size as f64 / post_residual as f64).min(1.0);
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Prefer bins with residual below mean (more filled bins first).
    score += 0.15 * (bin_residual as f64 - mean_residual);

    // Early stream: favor opening new bins for large items to preserve flexibility.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // New-bin cost baseline: only attractive when fit is poor elsewhere
        // or item is large relative to capacity.
        let large_item = item_size as f64 / bin_capacity as f64;
        score += 20.0 - 30.0 * large_item - 15.0 * (1.0 - progress);
        if next_item_size > 0 && next_item_size >= post_residual.max(1) {
            score -= 5.0;
        }
    } else {
        // Slight bonus for using already-open bins when many are open.
        score -= 0.05 * open_bins_count as f64;
    }

    // Penalize very small post-residuals that become unusable (< 10% capacity)
    // unless the item itself nearly fills the bin.
    if post_residual > 0 && post_residual < bin_capacity / 10 {
        score += 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += (10.0 - post_residual as f64) * 12.0;
    }
    // Mid-range gaps (10..=20) mildly penalized: hard to fill later.
    else if post_residual >= 10 && post_residual <= 20 {
        score += (20.0 - post_residual as f64) * 2.0;
    }

    // Reward very tight fits (near-perfect packing).
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 30.0;
    }

    // Bonus if the leftover can still fit the lookahead item (k=2 lookahead).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0 + next_item_size as f64 * 0.3;
    }
    // Penalize if leftover is nonzero but cannot fit the next item (dead space).
    else if next_item_size > 0 && post_residual > 0 {
        score += 8.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: discourage spreading across many open bins,
    // but favor filling existing bins rather than opening new ones.
    score += open_bins_count as f64 * 0.5;

    // Prefer bins below the mean residual (fill fuller bins first).
    score += (bin_residual as f64 - mean_residual) * 0.4;

    // New-bin candidate: make empty bins moderately attractive only when
    // current bins would create dead space; otherwise discourage opening.
    if bin_residual == bin_capacity {
        score += 35.0 - open_bins_count as f64 * 2.0;
        if post_residual < 20 {
            // item is large relative to capacity: opening fresh bin is fine
            score -= 20.0;
        }
    }

    // Late-stream tightening: as the stream progresses, avoid creating gaps.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += post_residual as f64 * progress * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: strongly reward bins whose post_residual
    // can host the next item (perfect 2-item packing).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            // Exact 2-item fill: ideal, heavily favored.
            score -= 200.0;
        } else if post_residual > next_item_size {
            // Next item fits; reward by tightness of the leftover-after-next gap.
            let gap = (post_residual - next_item_size) as f64;
            score -= 100.0 - gap * 0.5;
        } else {
            // Next item does not fit; penalize proportionally to the overshoot.
            let over = (next_item_size - post_residual) as f64;
            score += over * 0.8;
        }
    }

    // Penalize creating dead space relative to the fleet's mean residual:
    // a post_residual far below mean_residual is likely unusable waste.
    let dead = mean_residual - post_residual as f64;
    if dead > 0.0 {
        score += dead * 0.3;
    } else {
        score += dead * 0.1; // mild bonus for staying roomier than average
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 60.0;
    }

    // Mild pressure against accumulating too many open bins late in the stream.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += open_bins_count as f64 * progress * 0.5;

    // Slight preference for tighter fits overall.
    score += (item_size as f64 / bin_capacity as f64) * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual <= 10 {
        score += (11.0 - post_residual as f64) * 12.0;
    } else if post_residual == 0 {
        // Perfect fit is heavily rewarded.
        score -= 40.0;
    }

    // Reward tight fits relative to bin residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill_ratio * 15.0;

    // Open-bin pressure: prefer consolidating when many bins are open.
    score += open_bins_count as f64 * 0.8;

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if the next item can use the post residual, reward leaving it.
    if next_item_size > 0 {
        if (post_residual as f64) >= next_item_size as f64 {
            score -= 6.0;
        } else if next_item_size as f64 > post_residual as f64 && post_residual > 0 {
            score += 4.0;
        }
    }

    // New-bin candidate: only attractive when existing bins would leave bad gaps.
    if bin_residual == bin_capacity {
        score += 10.0 + open_bins_count as f64 * -0.5;
        if post_residual > 0 && post_residual <= 10 {
            // never open a fresh bin for a near-perfect fit elsewhere
            score += 100.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let pr_norm = pr / cap;

    // Base: prefer tight fits (low post residual), with non-linear shaping.
    let mut score = pr;
    score += 40.0 * pr_norm * pr_norm * (1.0 - pr_norm);

    // Stream-progress coupling: early on tolerate slack in big bins (they may absorb
    // future items); later, squeeze tighter. Smooth polynomial in progress.
    let tightness = 0.5 + 2.0 * progress * (3.0 - 2.0 * progress); // 0.5 -> 2.5
    score += tightness * pr;

    // Lookahead: reward bins whose post-residual can still hold the next item
    // (keeps chains alive); penalize post-residuals that strand tiny dead space.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr >= nx {
            score -= 8.0 + 6.0 * progress;
        } else {
            score += 5.0 * (nx - pr) / cap * 100.0;
        }
        // Perfect chain fit: post residual exactly matches next item.
        if (pr - nx).abs() < 0.5 {
            score -= 10.0;
        }
    } else {
        // Last item: only waste matters.
        score += 10.0 * pr_norm * pr_norm * cap;
    }

    // Dead-space penalty for awkward small residuals.
    if pr > 0 && pr < 10.0 {
        score += 15.0 * (10.0 - pr as f64) / 10.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate: neutral baseline, mildly encouraged early when open bins
    // are congested (mean residual low) to spread load.
    if bin_residual == bin_capacity {
        let congestion = mean_residual / cap;
        score = 60.0 - 25.0 * congestion * (1.0 - progress) + 30.0 * progress;
    }

    // Mild penalty for proliferating bins mid-stream.
    score += (open_bins_count as f64).ln().max(0.0) * 2.0 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let residual_f = post_residual as f64;
    let cap_f = bin_capacity as f64;
    let mut score = residual_f;

    // Exact 2-step chain: post_residual perfectly absorbs the next item
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 94.0;
        } else if post_residual > next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            let tightness = 1.0 - (slack / cap_f).min(1.0);
            score -= 14.0 + slack * 0.3 + tightness * 12.0;
            if (slack as u32) >= next_item_size {
                score -= 11.0;
                if slack >= 2.0 * next_item_size as f64 {
                    score -= 7.0;
                }
            }
        } else if post_residual > 0 {
            let gap = (next_item_size - post_residual) as f64;
            score += gap * 0.92;
        }
    }

    // Density coupling: prefer bins tighter than mean residual
    let density_gap = (mean_residual - residual_f) / cap_f;
    score -= density_gap * 33.0;

    // Last-chance bin: strongly favor using the only fitting bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 29.0;
    }
    // Scarce-fit pressure: when few bins fit, reward any fitting bin proportionally
    else if fitting_bins_count > 0 && fitting_bins_count <= 3 && bin_residual != bin_capacity {
        score -= (4.0 - fitting_bins_count as f64) * 5.2;
    }

    // New-bin candidate logic
    if bin_residual == bin_capacity {
        if next_item_size > 0 && (item_size + next_item_size) == bin_capacity {
            score -= 44.0;
        } else if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score -= 9.0;
        } else {
            // Scale open-bin penalty with how wasteful existing bins are
            let waste_factor = ((mean_residual / cap_f) - 0.1).max(0.0);
            score += 27.0 + 0.2 * open_bins_count as f64 + waste_factor * 21.0;
        }
    }

    // Late-stream consolidation: penalize leaving large residuals as stream progresses
    if total_items > 0 {
        let progress = step_index as f64 / total_items as f64;
        score += progress * progress * 14.0 * (residual_f / cap_f);
    }

    // Small tie-break: prefer filling bins with higher current fill
    score -= (bin_residual as f64 / cap_f) * 4.8;

    // Dead-space guard: penalize residuals too small for typical upcoming items
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 0.40;
    }

    // Fragmentation guard: residuals below half of next item are nearly dead
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size / 2 {
        score += 9.5;
    }

    // Perfect-completion bonus: bin becomes exactly full after this item
    if post_residual == 0 && bin_residual != bin_capacity {
        score -= 16.0;
    }

    // Reward post_residual that is a divisor-like fit (multiple of next item) —
    // enables chained perfect fills and reduces dead space.
    if next_item_size > 0 && post_residual >= next_item_size && post_residual % next_item_size == 0 && post_residual != next_item_size {
        let multiples = post_residual / next_item_size;
        if multiples <= 4 {
            score -= 6.0 + multiples as f64 * 2.0;
        }
    }

    // Penalize residuals that are awkwardly small relative to next item,
    // scaled by stream progress.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
