        // If post residual leaves a gap the next item nearly fills, slight reward
        if post_residual > next_item_size && (post_residual - next_item_size) < 10 {
            score -= 5.0;
        }
    }

    // Time horizon: early in the stream, be more willing to open new bins
    // (keep bins flexible); late in the stream, pack tightly into existing bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let new_bin_penalty = 20.0 + 40.0 * progress;
    if bin_residual == bin_capacity {
        // New bin candidate: base cost, reduced early, increased late.
        score += new_bin_penalty;
        // Large items are better served by a fresh bin.
        if item_size > bin_capacity / 2 {
            score -= 10.0;
        }
    }

    // Prefer bins whose residual is above average (use loose bins first),
    // keeping tight bins for future tight fits.
    score += (bin_residual as f64 - mean_residual) * 0.15;

    // Many open bins: encourage consolidation into existing bins.
    score += (open_bins_count as f64).ln().max(0.0) * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr_norm = pr / cap;

    // Base: penalize wasted residual, with a non-linear (quadratic) waste curve
    let mut score = pr + 40.0 * pr_norm * pr_norm * cap;

    // Stream-progress coupling: later in the stream, residual waste matters more
    // (fewer future items to fill leftovers), so amplify waste quadratically in progress.
    score *= 1.0 + 1.5 * progress * progress;

    // Smooth interaction: post_residual vs next_item_size — reward bins whose
    // post-residual smoothly matches the next item (good chaining), via a
    // normalized gap term raised to a power.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = (pr - nxt) / cap;
        if gap >= 0.0 {
            // next item fits: reward proportionally to how snugly it fits
            score -= 25.0 * (1.0 - gap) * (1.0 - gap);
        } else {
            // next item won't fit: mild smooth penalty growing with mismatch
            score += 8.0 * (-gap) * (-gap) * cap * 0.1;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // (avoid opening a new bin), scaled smoothly by how tight the fit is.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        let tightness = 1.0 - pr_norm;
        score -= 60.0 + 40.0 * tightness;
    }

    // New-bin candidate: penalize opening a new bin, more so when good fitting
    // bins exist and mean residual is healthy (smooth logistic-like term).
    if bin_residual == bin_capacity {
        let fill = (mean_residual / cap).clamp(0.0, 1.0);
        let logistic = 1.0 / (1.0 + (-6.0 * (fill - 0.5)).exp());
        score += 30.0 + 50.0 * logistic + 5.0 * open_bins_count as f64;
    }

    // Slight penalty for many open bins with large residuals (fragmentation pressure)
    score += 0.5 * (open_bins_count as f64) * pr_norm * pr_norm;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class of post_residual: dead space that is too small to fit
    // typical items is wasted. Classify via capacity fractions.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let quarter = cap * 0.25;
    let tenth = cap * 0.10;

    if pr < tenth {
        // Unusable dead space: penalize heavily (waste)
        score += (tenth - pr) * 3.0;
    } else if pr < quarter {
        // Small pocket: mildly penalize unless next item fits
        if next_item_size > 0 && (next_item_size as u32) <= post_residual {
            score -= 15.0;
        } else {
            score += (quarter - pr) * 0.5;
        }
    }

    // Integer-division thresholds: post_residual divisible by common item
    // sizes is more reusable (harmonic residue classes)
    if post_residual >= 10 && post_residual % 10 == 0 {
        score -= 10.0;
    }
    if post_residual % 5 == 0 {
        score -= 3.0;
    }

    // Last-chance bin bonus
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // Prefer tight fits: reward small post_residual generally
    score -= (cap - pr) / cap * 5.0;

    // Lookahead: if next item exactly fills post_residual, strong reward
    if next_item_size > 0 && (next_item_size as u32) == post_residual {
        score -= 50.0;
    }

    // New-bin candidate: only attractive when no open bin fits well
    if bin_residual == bin_capacity {
        // Base penalty to prefer reusing open bins
        score += 30.0;
        if fitting_bins_count == 0 {
            score -= 100.0;
        } else if fitting_bins_count == 1 {
            // Let last-chance bins win unless post_residual would be tiny
            score += if post_residual < 10 { 0.0 } else { 25.0 };
        }
        // Early stream: opening bins early is fine
        if total_items > 0 && step_index < total_items / 4 {
            score -= 10.0;
        }
    }

    // Mean residual coupling: if this bin's residual is far below mean,
    // it's already "tight" — finishing it is good
    if (bin_residual as f64) < mean_residual {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps below the minimum item size (1..=10)
    // are pure waste; penalize them quadratically.
    if post_residual < 10 && post_residual > 0 {
        score += 60.0 + (10 - post_residual) as f64 * 8.0;
    }

    // Perfect fit: strongly reward.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Tight fit: reward when post_residual is small relative to capacity.
    let tightness = post_residual as f64 / bin_capacity as f64;
    score -= 25.0 * (1.0 - 2.0 * tightness).max(0.0);

    // Last chance: strongly favor using the only bin that fits,
    // especially when the fit is decent.
    if fitting_bins_count == 1 {
        score -= 30.0;
        if post_residual < 15 {
            score -= 20.0;
        }
    }

    // Open-bin pressure: many open bins -> prefer consolidating into existing ones;
    // penalize opening new bins when pressure is high.
    let pressure = open_bins_count as f64 / (1.0 + step_index as f64).max(1.0);
    if bin_residual == bin_capacity {
        // New-bin candidate: only attractive when pressure is low or current
        // placements would create bad dead space.
        score += 18.0 * pressure;
        if post_residual == bin_capacity as u32 && next_item_size > 0 && next_item_size >= item_size {
            score -= 12.0;
        }
    } else {
        score -= 6.0 * pressure.min(3.0);
    }

    // Lookahead: if the next item fits exactly in post_residual, reward heavily.
    if next_item_size > 0 && post_residual > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            score -= 10.0;
        } else if next_item_size > post_residual && post_residual < 10 {
            score += 15.0; // dead space confirmed by lookahead
        }
    }

    // Alignment with mean residual: prefer bins close to the mean to keep
    // residual distribution balanced.
    score += 0.15 * ((post_residual as f64 - mean_residual).abs());

    // Late in the stream: be more conservative, avoid leaving tiny gaps.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 10.0 * progress * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // New-bin candidate: neutral-ish baseline, slightly above good fits.
    if bin_residual == bin_capacity {
        return 55.0 + (post_residual as f64) * 0.1;
    }

    let post = post_residual as f64;

    // Two-step lookahead: perfect match with next item is ideal.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0; // exact 2-item completion
        } else if post_residual > next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            // Small slack means next item still fits well afterward.
            score -= 25.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item cannot follow: dead space unless another bin takes it.
            let gap = (next_item_size - post_residual) as f64;
            score += 8.0 + gap * 0.15;
        }
    } else {
        // Last item: minimize waste directly.
        score += 0.0;
    }

    // Penalize tiny unusable residuals (dead space < typical min item).
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }
    // Reward zero residual (perfectly closed bin).
    if post_residual == 0 {
        score -= 40.0;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 18.0;
    } else if fitting_bins_count > 1 {
        // Among many fitting bins, prefer tighter fits (already via post_residual).
        score += 0.0;
    }

    // Relative to mean residual: bins tighter than average are better targets.
    score -= (mean_residual - post) * 0.05;

    // Early in stream: be slightly conservative, keep bins flexible.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += (1.0 - progress) * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: quadratic bonus for small post-residual
    let tight = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tight * tight;

    // Dead-space penalty for awkward residuals (hard to fill later)
    if post_residual > 0 && post_residual < 10 {
        score += 18.0;
    }

    // Lookahead coupling: if next item fits exactly in post-residual, strong reward
    if next_item_size > 0 {
        let diff = post_residual as i64 - next_item_size as i64;
        if diff == 0 {
            score -= 25.0;
        } else if diff > 0 && diff < 15 {
            score -= 8.0;
        } else if diff < 0 {
            // next item won't fit here; slight penalty proportional to overflow
            score += (diff.abs() as f64) * 0.15;
        }
        // Prefer bins whose post-residual stays flexible for average-sized items
        let mid = 35.0;
        let flex = 1.0 - ((post_residual as f64 - mid).abs() / 60.0).min(1.0);
        score -= 6.0 * flex;
    } else {
        // End of stream: prioritize minimizing waste directly
        score += 5.0 * (post_residual as f64 / bin_capacity as f64);
    }

    // Last-chance bin: strong reward to avoid opening a new bin unnecessarily
    if fitting_bins_count == 1 {
        score -= 20.0;
    } else if fitting_bins_count > 2 {
        // many alternatives: be pickier, penalize loose fits
        score += 3.0 * (post_residual as f64 / bin_capacity as f64);
    }

    // Global pressure: many open bins with high mean residual -> consolidate
    let pressure = mean_residual / bin_capacity as f64;
    if open_bins_count > 3 && pressure > 0.4 {
        score -= 4.0 * pressure * (open_bins_count as f64).ln();
    }

    // Time horizon: early in stream, allow new bins / keep flexibility;
    // late in stream, squeeze into existing bins harder.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 10.0 * progress * tight;
    score += 6.0 * (1.0 - progress) * (post_residual as f64 / bin_capacity as f64);

    // New-bin candidate: acceptable early or when item is huge and nothing fits well
    if bin_residual == bin_capacity {
        let big_item = item_size as f64 / bin_capacity as f64;
        if progress < 0.25 || big_item > 0.7 || fitting_bins_count == 0 {
            score -= 4.0;
        } else {
            score += 10.0 * progress;
        }
    }

    // Waste-rate coupling: item nearly fills bin exactly across residual scale
    let exactness = (item_size as f64 / bin_residual.max(1) as f64).min(1.0);
    score -= 5.0 * exactness * exactness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr_norm = pr / cap;

    // Base: penalize remaining residual, but with non-linear saturation
    // so tiny residuals are extra attractive (tight fits).
    let mut score = pr_norm * (1.0 + 2.0 * pr_norm * (1.0 - pr_norm));

    // Smooth polynomial coupling of residual with stream progress:
    // early on, prefer filling bins loosely (keep flexibility);
    // late, strongly prefer tight packing.
    let tightness_bias = pr_norm * pr_norm * (progress * 1.8 + 0.2);
    score += tightness_bias * cap * 0.5;

    // Dead-space penalty: residual too small for typical next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let waste = (nxt - pr).max(0.0) / cap;
        score += waste * waste * 12.0 * (0.5 + progress);
        // Reward bins whose post-residual can host the next item
        if pr >= nxt {
            score -= 0.6 * (1.0 - pr_norm) * (1.0 - progress * 0.5);
        }
    } else {
        // Last item: pure tightness
        score += pr_norm * pr_norm * 4.0;
    }

    // Last-chance bonus: only one fitting bin -> favor using it
    if fitting_bins_count == 1 {
        score -= 1.5 * (1.0 - pr_norm);
    } else if fitting_bins_count > 1 {
        // mild competition pressure: prefer tighter among many
        score += 0.1 * fitting_bins_count as f64 * pr_norm;
    }

    // Slight preference to spread across bins when many open with slack
    score += 0.05 * (mean_residual - pr).abs() / cap;

    // New-bin candidate: penalize opening a fresh bin unless residuals are bad
    if bin_residual == bin_capacity {
        let avg_slack = mean_residual / cap;
        score += 2.0 + 3.0 * (1.0 - avg_slack) * (1.0 - progress * 0.3);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the residual: classify post_residual into capacity-fraction bands.
    let frac = post_residual as f64 / bin_capacity as f64;
    // Dead-space penalty grows sharply for tiny unusable residuals (0 < post_residual < 10).
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }
    // Perfect fit is heavily rewarded.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Harmonic classes via integer division: residuals in [0..12], [12..25], [25..50], [50..100]
    let class = post_residual / 25; // 0,1,2,3 harmonic class
    score += match class {
        0 => 15.0,           // very tight leftover: risky dead space
        1 => 5.0,            // small residual: only fits tiny items
        2 => 0.0,            // medium: usable
        _ => -8.0,           // large residual remains: bin still flexible
    };

    // Lookahead coupling: reward if next item fits into post_residual.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 12.0 + 0.1 * next_item_size as f64;
        } else {
            // Next item won't fit here; if this bin was the only fitting bin, opening a
            // fresh bin for the pair may be better.
            score += 4.0;
        }
        // Harmonic compatibility: next item leaves a well-classed residual if placed here.
        if next_item_size <= post_residual {
            let nr = post_residual - next_item_size;
            if nr == 0 {
                score -= 20.0;
            } else if nr < 10 {
                score += 10.0;
            }
        }
    }

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Prefer bins tighter than the mean (best-fit flavor, modulated by stream progress).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (mean_residual - bin_residual as f64).max(-50.0).min(50.0) * (0.3 + 0.4 * progress);

    // Late in the stream, discourage opening new bins.
    if bin_residual == bin_capacity {
        score += 20.0 + 30.0 * progress + 2.0 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: unusable small gaps are heavily penalized.
    // A gap is "dead" if the next item cannot use it (post_residual < next_item_size)
    // and it is small enough that no realistic item (>= 1, but small) would fit usefully.
    if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        // Gap smaller than the next item: penalize proportionally to how wasted it is.
        let waste_ratio = post_residual as f64 / next_item_size as f64;
        score += 8.0 + 6.0 * (1.0 - waste_ratio);
    }

    // Very small dead gaps (< 10) are almost certainly unusable ever.
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    // Reward perfect or near-perfect fits.
    if post_residual == 0 {
        score -= 15.0;
    } else if post_residual <= 5 {
        score -= 6.0;
    }

    // Reward using a gap that exactly accommodates the next item (lookahead pairing).
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 10.0;
    }

    // Open-bins pressure: with many open bins, prefer filling existing bins
    // rather than spreading; with few open bins, mild pressure to consolidate.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = (open_bins_count as f64).ln() * (1.0 + progress);
    score += 0.8 * pressure * (post_residual as f64 / bin_capacity as f64);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 9.0;
    }

    // New-bin candidate: only attractive when the item fits poorly everywhere
    // else (large post_residual would be created) or few bins are open.
    if bin_residual == bin_capacity {
        // Baseline for a fresh bin: keep it competitive but slightly penalized
        // so tight fits into existing bins win.
        score += 3.0;
        if open_bins_count < 3 {
            score -= 5.0;
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 4.0;
        }
    }

    // Mean-residual coupling: if the fleet average residual is high, tolerate
    // slightly worse fits here (spread waste); if low, be strict.
    score += 0.05 * (mean_residual - post_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
