    score += 0.3 * (mean_residual - post_residual as f64).abs();

    // Last-chance bin: strongly prefer using it over opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Penalize opening a new bin when open bins exist and the item fits reasonably
    if bin_residual == bin_capacity {
        let fit_ratio = (item_size as f64) / (bin_capacity as f64);
        score += 25.0 + 20.0 * fit_ratio;
        if open_bins_count > 0 && (item_size as f64) <= mean_residual {
            score += 30.0;
        }
        // Late in stream, avoid proliferating bins
        let progress = step_index as f64 / (total_items.max(1) as f64);
