}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = (step_index as f64 / total_items as f64).clamp(0.0, 1.0);
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let it = item_size as f64;

    // Base: post_residual, with non-linear polynomial coupling to stream progress.
    let mut score = pr * (1.0 + 0.5 * progress * (1.0 - pr / cap));

    // Quadratic dead-space penalty: small residuals are wasteful, but the
    // penalty smooths out as the stream progresses (less future to protect).
    let dead = (pr / cap).powi(2);
    score += 30.0 * dead * (1.0 - progress) * (1.0 - progress);

    // Reward tight fits: subtract a smooth bell around small post_residual.
    let tight = (-((pr / cap - 0.05) * 12.0).powi(2)).exp();
    score -= 20.0 * tight;

    // Lookahead coupling: if next item fits exactly in post_residual, reward strongly.
    if next_item_size > 0 {
        let gap = (pr - next_item_size as f64).abs();
        let match_bell = (-(gap / 10.0).powi(2)).exp();
        score -= 15.0 * match_bell;
    } else {
        // Last item: purely minimize waste.
        score += pr * 0.3;
    }

    // Scarcity pressure: when few bins can fit the item, favor using this one.
    if fitting_bins_count <= 1 {
        score -= 25.0;
    } else {
        score -= 8.0 / fitting_bins_count as f64;
    }

    // Open-bin count pressure: mildly discourage fragmenting into many bins early.
    score += 0.3 * open_bins_count as f64 * (1.0 - progress);

    // Mean-residual coupling: prefer bins whose residual deviates from the mean
    // in the direction of tighter packing (below-mean residual is good use).
    score += 0.1 * (pr - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: partition capacity into 4 classes.
    let quarter = bin_capacity / 4;
    let class = match post_residual {
        0 => 0u32,
        x if x < quarter => 1,
        x if x < 2 * quarter => 2,
        x if x < 3 * quarter => 3,
        _ => 4,
    };
    // Reward tight fits (low class) heavily.
    score -= (4 - class) as f64 * 12.0;

    // Perfect fit: huge reward.
    if post_residual == 0 {
        score -= 200.0;
    }

    // Modulo arithmetic: post_residual divisible by common item sizes is reusable.
    if post_residual > 0 {
        let mut reusable = 0.0f64;
        for d in [10u32, 20, 25, 50, 5] {
            if post_residual % d == 0 {
                reusable += 6.0;
            }
        }
        score -= reusable;
    }

    // Dead-space penalty: small awkward residue that likely cannot host anything.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // Lookahead: if next item fits exactly into post_residual, reward strongly.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 150.0;
        } else if next_item_size < post_residual {
            let gap = post_residual - next_item_size;
            score -= 25.0 * (1.0 - gap as f64 / bin_capacity as f64);
        } else {
            // Next item won't fit here; penalize wasting large residuals on small items.
            score += 8.0;
        }
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 60.0;
    }

    // Penalize new-bin candidate slightly so it only wins when open bins are bad.
    if bin_residual == bin_capacity {
        score += 30.0 + open_bins_count as f64;
    }

    // Prefer filling bins below mean residual (consolidate space).
    score += (bin_residual as f64 - mean_residual) * 0.3;

    // Late in stream: push toward tighter packing.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.2 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 15 {
        score += (15.0 - post_residual as f64) * 6.0;
    }

    // Perfect fit is strongly rewarded.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Reward leaving gaps that can still host future items (useful residual).
    let progress = step_index as f64 / total_items.max(1) as f64;
    if post_residual >= 15 {
        score -= 8.0;
        // If next item fits into the post residual, reward more (chain packing).
        if next_item_size > 0 && (next_item_size as u32) <= post_residual {
            score -= 12.0 * (1.0 - 0.5 * progress);
        }
    }

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: penalize opening extra bins, more when few bins open.
    if bin_residual == bin_capacity {
        score += 25.0 + 4.0 * (open_bins_count as f64).sqrt();
        // Opening a new bin is acceptable if the item would leave a big useful gap anyway
        // or if the fit elsewhere is terrible; slight relief with lookahead.
        if next_item_size > 0 && next_item_size >= 60 && next_item_size <= bin_capacity {
            score -= 10.0;
        }
    }

    // Pressure from too many open bins: prefer consolidating into existing bins.
    score += open_bins_count as f64 * 0.8;

    // Prefer bins with residual close to what the item consumes (tight packing),
    // but only when the gap is usable.
    let gap = (bin_residual as f64 - item_size as f64).max(0.0);
    if gap >= 15.0 {
        score -= 3.0 * (1.0 - (gap / bin_capacity as f64)).min(1.0);
    }

    // Slight preference for bins below mean residual (fills emptier bins first,
    // keeping tight bins for tight fits).
    score += (mean_residual - bin_residual as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

