pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize less when the item nearly fills the bin.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 25.0 * fit_ratio * fit_ratio;

    // Penalize dead space: post_residual that is too small to hold a typical
    // future item (items >= 1, but small residuals waste capacity).
    if post_residual > 0 {
        let dead = (post_residual as f64 / bin_capacity as f64).powf(2.0);
        score += 40.0 * dead;
    } else {
        // Perfect fill is ideal.
        score -= 30.0;
    }

    // Last-chance bonus: if this is the only bin that can fit the item,
    // strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
    }

    // Lookahead: if the next item fits exactly in the post-residual, reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0;
        } else if next_item_size <= post_residual {
            // Next item fits but leaves residue: mild reward proportional to fit.
            score -= 15.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // Next item cannot use the leftover: penalize proportionally.
            score += 10.0 * (1.0 - post_residual as f64 / next_item_size as f64).min(1.0);
        }
    }

    // Prefer bins with residuals below the mean (pack the emptier/tighter bins
    // first to consolidate), scaled by current bin pressure.
    score += 0.3 * (bin_residual as f64 - mean_residual).max(-50.0).min(50.0);

    // Time horizon: late in the stream, avoid opening new bins; early on,
    // allow some exploration of fresh bins for large items.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let new_bin_bonus = if bin_residual == bin_capacity {
        // New-bin candidate: base score plus pressure adjustments.
        let openness = (1.0 - progress) * 20.0;
        let crowding = open_bins_count as f64 * 2.0;
        15.0 + openness + crowding
            - if item_size >= 50 { 25.0 } else { 0.0 }
            - if fitting_bins_count == 0 { 100.0 } else { 0.0 }
    } else {
        0.0
    };
    score += new_bin_bonus;

    // Late stream: extra penalty for new bins to force consolidation.
    if progress > 0.7 && bin_residual == bin_capacity {
        score += 30.0 * progress;
    }

    // Slight preference for bins whose residual is close to item_size + next_item_size.
    if next_item_size > 0 {
        let combo = item_size as f64 + next_item_size as f64;
        let gap = (bin_residual as f64 - combo).abs();
        score += 0.15 * gap;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: post-residual with smooth non-linear penalty on small residuals (dead space)
    let mut score = pr * (1.0 + 0.8 * (1.0 - norm_pr) * (1.0 - norm_pr));

    // Smooth polynomial coupling of post_residual with stream progress:
    // early on, waste matters less; late, prefer tight fills strongly.
    let tightness = 1.0 - norm_pr;
    score += progress * pr * (1.5 * tightness - 0.5) * tightness;

    // Reward last-chance bins (avoid opening new bins unnecessarily)
    if fitting_bins_count == 1 {
        score -= 12.0 * (1.0 - progress);
        score -= 6.0;
    }

    // Prefer bins whose residual is close to the mean (balance)
    score += 0.3 * (pr - mean_residual).abs();

