        } else if next_item_size as f64 <= pr {
            score -= 3.0 * (1.0 - diff / cap);
        }
    }

    // Mild penalty for many open bins to encourage consolidation
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class: bucket post_residual into capacity fractions
    let frac = post_residual as f64 / bin_capacity as f64;

    // Penalize residual classes that are hard to fill (dead space zones).
    // Residuals in (0,10] are nearly dead; (10,30] moderately usable.
    if post_residual == 0 {
