    } else {
        score += (5 - (mod10 as i32).abs() ) as f64 * 0.4;
    }

    // Lookahead coupling: if next item fits exactly into post_residual,
    // strongly reward this bin (chain fit).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            let next_post = post_residual - next_item_size;
            // reward chain fits that also leave harmonic residuals
            score -= 10.0 * (1.0 - (next_post as f64 / bin_capacity as f64));
            if next_post % 10 == 0 {
                score -= 5.0;
            }
        } else {
            // next item won't fit here; penalize proportionally to wasted potential
            score += 4.0 * (next_item_size - post_residual) as f64 / bin_capacity as f64;
        }
    }

    // Last-chance bin: if this is the only fitting bin, prefer using it over
    // opening a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate: make it moderately attractive only when the item is
    // large relative to the residual (poor fit into open bins) or few bins open.
    if bin_residual == bin_capacity {
        let tightness = item_size as f64 / bin_capacity as f64;
        // Early stream or big item: fresh bin is fine; late stream with small
        // item and many open bins: discourage waste.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 18.0 * (1.0 - tightness) + 10.0 * (1.0 - progress);
        if open_bins_count == 0 {
