            score += 15.0; // discourage abandoning open bins late for small items
        }
    }

    // Mean residual coupling: when open bins are already slack, prefer bins
    // below the mean (tighter bins) to consolidate slack.
    if bin_residual != bin_capacity {
        score += 0.5 * (mean_residual - bin_residual as f64);
    }

    // Mild penalty per open bin to encourage bin consolidation overall.
    score += 0.05 * open_bins_count as f64;

    score
}

