        }
    }

    // --- Last-chance bonus: only this bin can host the item ---
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // --- New-bin candidate logic: open a fresh bin when it preserves utility ---
    if bin_residual == bin_capacity {
        score -= 15.0; // fresh bins are valuable by default over poor fits
        if next_item_size > 0 && post_residual >= next_item_size {
