            if (slack as u32) >= next_item_size {
                score -= 11.0;
                if slack >= 2.0 * next_item_size as f64 {
                    score -= 7.0;
                }
            }
        } else if post_residual > 0 {
            let gap = (next_item_size - post_residual) as f64;
            score += gap * 0.9;
        }
    }

    // Density coupling: prefer bins tighter than mean residual
    let density_gap = (mean_residual - residual_f) / cap_f;
    score -= density_gap * 32.0;

    // Last-chance bin: strongly favor using the only fitting bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 28.0;
    }
    // Scarce-fit pressure: when few bins fit, reward any fitting bin proportionally
    else if fitting_bins_count > 0 && fitting_bins_count <= 3 && bin_residual != bin_capacity {
        score -= (4.0 - fitting_bins_count as f64) * 5.0;
    }

    // New-bin candidate logic
    if bin_residual == bin_capacity {
        if next_item_size > 0 && (item_size + next_item_size) == bin_capacity {
            score -= 42.0;
        } else if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score -= 9.0;
        } else {
            // Scale open-bin penalty with how wasteful existing bins are
            let waste_factor = ((mean_residual / cap_f) - 0.1).max(0.0);
            score += 26.0 + 0.2 * open_bins_count as f64 + waste_factor * 20.0;
        }
    }

    // Late-stream consolidation: penalize leaving large residuals as stream progresses
    if total_items > 0 {
        let progress = step_index as f64 / total_items as f64;
        score += progress * progress * 13.0 * (residual_f / cap_f);
    }

    // Small tie-break: prefer filling bins with higher current fill
    score -= (bin_residual as f64 / cap_f) * 4.5;

    // Dead-space guard: penalize residuals too small for typical upcoming items
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 0.38;
    }

    // Fragmentation guard: residuals below half of next item are nearly dead
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size / 2 {
        score += 9.0;
    }

    // Perfect-completion bonus: bin becomes exactly full after this item
    if post_residual == 0 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Dead-space ratio penalty: residuals that can never absorb common small
    // items (1..=10) are effectively wasted space; push the packer toward
    // bins whose post-residual stays usable.
    if post_residual > 0 && post_residual < 10 {
        score += 6.0 + (10 - post_residual) as f64 * 0.5;
    }

    // Near-perfect residual reward: leaving just enough room for a small
    // item range keeps bins closable quickly and reduces fragmentation.
    if post_residual >= 10 && post_residual <= 25 {
        score -= 5.0;
    }

    // Two-item lookahead: if the residual after placement could absorb
    // next_item plus a small follow-up, reward the chain further.
    if next_item_size > 0 && post_residual > next_item_size {
        let follow_up = post_residual - next_item_size;
        if follow_up >= 1 && follow_up <= 20 {
            score -= 4.0;
        }
    }

    // NEW: residual-utility scaling — reward post-residuals that remain a
    // usable fraction of the next item, penalize near-miss residuals that
    // just barely fail to absorb it (maximal dead space).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        let miss_ratio = post_residual as f64 / next_item_size as f64;
        if miss_ratio >= 0.75 {
            score += 7.0; // painful near-miss: almost usable but wasted
        }
    }

    // NEW: pair-completion lookahead — if post_residual equals the sum of a
    // plausible small follow-up pair, strongly favor this bin.
    if next_item_size > 0 && post_residual > next_item_size {
        let follow_up = post_residual - next_item_size;
        if follow_up == next_item_size {
            score -= 8.0;
        }
    }

    // NEW: late-stream new-bin suppression — as the stream progresses,
    // opening new bins is increasingly costly; raise the new-bin score so
    // existing bins absorb items unless the fit is genuinely excellent.
    if bin_residual == bin_capacity && total_items > 0 {
        let progress = step_index as f64 / total_items as f64;
        score += progress * 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let p = step_index as f64 / total_items.max(1) as f64;
    let norm_post = post / cap;

    // Base: prefer small post-residual (tight packing), scaled non-linearly.
    let mut score = post * (1.0 + 0.8 * norm_post * norm_post);

    // Smooth progress coupling: as stream advances, tighten preference for
    // near-full bins and penalize leaving medium gaps (hard to fill later).
    let gap_penalty = norm_post * (1.0 - norm_post); // peaks at half-full gaps
    score += 30.0 * gap_penalty * (0.4 + 0.6 * p);

    // Lookahead: reward bins whose post-residual can still host next item,
    // penalize post-residual that is awkwardly small for the next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post >= nxt {
            score -= 8.0 * (1.0 - (post - nxt) / cap);
        } else {
            let deficit = (nxt - post) / cap;
            score += 15.0 * deficit * deficit * (0.5 + 0.5 * p);
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 - norm_post * 0.5);
    }

    // Mean-residual coupling: when open bins are on average spacious,
    // filling this one is less critical; when they are tight, prefer it.
    let mean_norm = mean_residual / cap;
    score += 6.0 * mean_norm * (1.0 - norm_post);

    // Mild penalty for many open bins to encourage consolidation.
    score += 0.5 * open_bins_count as f64 * norm_post;

    // New-bin candidate: make it attractive only when no open bin fits well.
    if bin_residual == bin_capacity {
        let novelty_bias = 12.0 * (1.0 - p) + 6.0;
        score += novelty_bias;
    }

    score
}

