    } else if pr < 10 {
        score += 25.0; // tiny dead space is nearly unusable
    } else if pr <= 25 {
        score -= 15.0; // usable by small items (10..25)
    } else {
        score += pr_class as f64 * 0.6; // penalize awkward residues
    }

    // Lookahead coupling: if next item fits exactly in the post residual, big reward.
    if next_item_size > 0 {
        let next = next_item_size as i64;
        if next == pr {
            score -= 60.0;
        } else if next <= pr {
            let slack = (pr - next) as f64;
            score -= 20.0 - slack * 0.5;
            // modulo harmony: next item and residual share a class
            if (next % 10) == (pr % 10) {
                score -= 8.0;
            }
        } else {
