    // relative to the harmonic class of the item, or bins are few.
    if bin_residual == bin_capacity {
        let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let awkward = (bin_residual as i64 - item_size as i64) < 10;
        if awkward && open_bins_count > 2 {
            score -= 20.0 + 10.0 * t;
        } else {
