    if mod25 == 0 {
        score -= 8.0;                   // quarter-capacity aligned residual
    }
    if post_residual % 50 == 0 {
        score -= 6.0;                   // half-capacity aligned residual
    }

    // Perfect fit is ideal
    if post_residual == 0 {
        score -= 100.0;
    }

    // Lookahead coupling: does next item fit the post residual?
    if next_item_size > 0 {
        if next_item_size == post_residual {
