        && (post_residual - next_item_size) <= item_size.min(next_item_size) {
        score -= 4.0;
    }

    // Dead-space-vs-mean coupling
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size && residual_f > mean_residual {
        score += (residual_f - mean_residual) * 0.22 * (0.5 + progress);
    }

    // Mid-stream salvage threshold
    if next_item_size > 0 && post_residual >= next_item_size + 5 && fitting_bins_count > 2 && progress < 0.5 {
        score -= 3.5;
    }

    // NEW: dead-space escalation scaled by item size class — residuals dead for
    // LARGE next items (>30) are the costliest; penalize proportionally harder,
    // since large items are hardest to re-home later.
    if next_item_size > 30 && post_residual > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 0.18 * (1.0 + progress);
    }

    // NEW: perfect-split pairing — item exactly fills half of the post_residual,
    // leaving a symmetric remainder that pairs well with a repeat item.
    if next_item_size > 0 && post_residual > next_item_size
        && post_residual % 2 == 0 && (post_residual / 2) == next_item_size {
        score -= 6.0;
    }

    // NEW: golden-fit band — post_residual within 2 of a perfect complement
    // (bin_capacity - next_item_size) yields near-zero waste on the next step.
    if next_item_size > 0 && post_residual >= 2 {
        let complement = bin_capacity.saturating_sub(next_item_size);
