    // Very small dead space (< 10) is nearly unusable for typical items: penalize.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is truly terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0 + 0.3 * item_size as f64;
    }

    // Lookahead: if the next item fits into post_residual, reward this placement strongly.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 120.0 - 0.5 * (post_residual - next_item_size) as f64;
        } else {
            // Next item won't chain here; mildly penalize large leftovers when no chain.
            score += 0.2 * post_residual as f64;
        }
    }

    // Global state: if mean residual across open bins is high, we have slack everywhere;
    // prefer consolidating into the emptiest usable bin rather than fragmenting.
    score -= (bin_residual as f64 - mean_residual) * 0.15;

    // Many open bins: discourage opening new ones; encourage closing out tight bins.
    let t = step_index as f64 / total_items.max(1) as f64;
    let open_pressure = (open_bins_count as f64).ln() * 10.0;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when many bins are open or early in stream.
        score += 150.0 + open_pressure + 200.0 * (1.0 - t);
        // Allow a new bin only if no reasonable fit exists elsewhere.
        if fitting_bins_count == 0 {
            score -= 400.0;
