        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 5.0 * progress;
        } else {
            score += 6.0 * norm_pr * progress;
        }
    }

    // Harmony bonus: item exactly halves the residual
    if bin_residual > item_size && (bin_residual - item_size) == item_size {
        score -= 9.0;
    }

    // Small tie-break: prefer filling bins with higher current fill
    score -= (bin_residual as f64 / cap) * 4.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let x = pr / cap; // normalized post residual

    // Base: non-linear polynomial in normalized post-residual, modulated by stream progress.
    // Early on, prefer tight fills mildly; late in stream, reward tight fills strongly.
    let poly = 4.0 * x * x - 4.0 * x * x * x; // smooth hump peaking at x=2/3
    let mut score = pr * (1.0 + progress * (1.0 - poly)) + 20.0 * x * x * progress;

    // Penalize dead space relative to mean residual of open bins (smooth coupling).
    score += 0.15 * (pr - mean_residual).abs() * (0.5 + progress);

    // Lookahead: reward leaving room for the next item (smooth kernel).
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let diff = pr - nx;
        if diff >= 0.0 {
            let k = diff / cap;
            score -= 8.0 * (1.0 - k) * (1.0 - progress * 0.5);
        } else {
            score += 0.05 * (-diff);
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 * (0.5 + progress);
    }

