    // sizes (10..=50) are more reusable; reward them.
    let mut harmonic_bonus = 0.0f64;
    for d in [10u32, 20, 25, 50] {
        if post_residual % d == 0 && post_residual > 0 {
            harmonic_bonus += 8.0;
