    // three-quarter-full bins are natural "harmonic" targets.
    let half = bin_capacity / 2;
    let three_quarter = (bin_capacity * 3) / 4;
    if bin_residual >= three_quarter {
        score -= 6.0;
    } else if bin_residual >= half {
        score -= 3.0;
    } else {
        // Low-residual bins: filling them closes them out; small bonus.
        score -= 2.0;
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
