    // New-bin candidate: penalize opening a new bin unless existing fits are
    // poor (large post_residual) or there are no open bins.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 55.0 + 20.0 * progress;
        if open_bins_count == 0 {
            score -= 100.0;
