pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;

    // Normalized post-residual in [0, 1]
    let r = post / cap;

    // Smooth non-linear penalty on residual: small residuals are dead space,
    // very large residuals waste capacity. Use a smooth U-shaped polynomial.
    let waste_poly = 4.0 * r * (1.0 - r);          // peaks at r=0.5 (good fit)
    let dead_space = (1.0 - r) * (1.0 - r);        // penalizes tiny leftovers

    let mut score = post;

    // Reward residual profiles that sit near the "sweet spot" via polynomial coupling
    score -= 30.0 * waste_poly * (0.5 + 0.5 * progress);

    // Penalize dead space with a cubic coupling to item size
    score += 12.0 * dead_space * (item / cap) * (1.0 + progress);

    // Tight fit bonus: quadratic in item occupancy
    let occupancy = item / cap;
    score -= 25.0 * occupancy * occupancy;

    // Lookahead coupling: reward bins whose post-residual can host the next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post >= nxt {
            let slack = (post - nxt) / cap;
            score -= 15.0 * (1.0 - 4.0 * slack * (1.0 - slack));
        } else {
            // Infeasible for next item: smooth penalty proportional to shortfall
            let short = (nxt - post) / cap;
            score += 20.0 * short * short;
        }
    }

    // Last-chance bonus: only one fitting bin -> strongly favor using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0 * (1.0 - progress);
    }

    // New-bin candidate: make it mildly attractive only when existing bins fit poorly
    if bin_residual == bin_capacity {
        let avg_fit = mean_residual / cap;
        score += 10.0 + 20.0 * (1.0 - avg_fit) * (1.0 - progress);
        // discourage excessive bin proliferation late in the stream
        score += open_bins_count as f64 * 0.5 * progress;
    }

    // Mild preference to consolidate into bins below mean residual (fill emptier bins)
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 5.0 * dev * dev.abs();

    score
}

