        score -= 4.0;
    }

    // Mid-stream salvage threshold — keep versatile bins open when several compete
    if next_item_size > 0 && post_residual >= next_item_size + 5 && fitting_bins_count > 2 && progress < 0.5 {
        score -= 3.5;
    }

    // NEW: absolute dead-space threshold — residuals that can never fit the
    // global minimum plausible item (<= 5) are pure waste; escalate with progress
    if post_residual > 0 && post_residual <= 5 {
        score += 4.0 + progress * 10.0;
    }

    // NEW: versatility-normalized residual — favor residuals that are exact
    // multiples of the next item (clean future chains), scaled by remaining stream
    if next_item_size > 0 && post_residual >= next_item_size && post_residual % next_item_size == 0 {
        let chains = post_residual / next_item_size;
        score -= (chains as f64).min(4.0) * (1.5 + 3.0 * (1.0 - progress));
