        score += (residual_f - mean_residual * 1.4) * (0.10 + 0.25 * progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: reward residuals in reusable size classes
    // (small, chunky leftovers that future items can still fill).
    let pr = post_residual;
    if pr == 0 {
        score -= 60.0; // perfect fit, ideal
    } else if pr <= 5 {
        score -= 25.0; // near-perfect, negligible waste
    } else if pr <= 15 {
        score -= 5.0; // small dead space
    } else if pr <= 30 {
        score += 8.0; // medium leftover
    } else if pr <= 50 {
        score += 15.0; // large leftover, still somewhat reusable
    } else {
        score += 25.0; // huge leftover: we barely helped this bin
    }

    // Modulo-based harmonic classes: residuals that are multiples of common
    // item sizes (10/20/25/50) tend to be re-fillable exactly.
    if pr % 10 == 0 && pr > 0 {
        score -= 6.0;
    }
    if pr % 25 == 0 && pr > 0 {
        score -= 4.0;
    }
    if pr % 50 == 0 && pr > 0 {
        score -= 3.0;
    }

    // Lookahead: if next item fits exactly into the post residual, strong reward.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 30.0;
        } else if next_item_size <= pr {
            // next item fits: reward proportional to how well it fills leftover
            let fill = next_item_size as f64 / pr as f64;
            if fill > 0.7 {
                score -= 12.0 * fill;
            } else {
                score -= 4.0 * fill;
            }
        } else {
            // next item cannot use this leftover: penalize large leftovers more
            score += (pr.min(next_item_size.saturating_sub(1)) as f64) * 0.05;
        }
    }

    // Last-chance bonus: if this is the only bin that can fit the item,
    // strongly prefer it over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 40.0;
    } else if fitting_bins_count == 2 {
        score -= 10.0;
    }

    // New-bin candidate: only attractive when item is large relative to mean
    // residual or no open bin is a good fit. Penalize opening new bins mildly
    // so existing bins with decent fits win.
    if bin_residual == bin_capacity {
        // fresh bin: post_residual == capacity - item_size; score starts there.
        // Penalize unless item is big (little waste left) or few fitting bins.
        let waste = post_residual as f64;
