    // in a small quantized band (good chain candidates), mid-stream weighted.
    if next_item_size > 0 && post_residual > next_item_size {
        let slack = post_residual - next_item_size;
        if slack <= 12 {
            score -= (13 - slack as i32) as f64 * 0.9 * (1.0 - progress * 0.5);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small to fit the minimum
    // item size are unusable "dead" space -> heavy penalty.
    let dead_threshold: u32 = 10;
    if post_residual > 0 && post_residual < dead_threshold {
        score += 25.0 + (dead_threshold - post_residual) as f64 * 3.0;
    }

    // Reward near-perfect fits (post_residual close to 0 but usable).
    if post_residual == 0 {
        score -= 30.0; // perfect fill
    } else if post_residual <= 20 {
        score -= 10.0 - post_residual as f64 * 0.3;
    }

    // Coupling with next item lookahead: if the next item fits exactly in
    // the post residual, strongly favor this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
        if post_residual == next_item_size {
            score -= 12.0;
        }
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // residual can't host the next item -> slight penalty for dead space
        score += 5.0;
    }

    // Open bins pressure: discourage spreading when many bins are open,
    // but allow opening a new bin when this bin would leave a bad gap.
    let open_pressure = (open_bins_count as f64).ln().max(0.0) * 2.0;
    if bin_residual == bin_capacity {
        // New-bin candidate: attractive only if it avoids small dead space.
        score += open_pressure;
        if item_size >= bin_capacity - dead_threshold {
            score -= 15.0; // large item fills a fresh bin nicely
        }
    } else {
        score -= open_pressure * 0.5;
    }

    // Last-chance bonus: if this is the only bin that fits, use it rather
    // than opening a new one (unless dead space would be severe).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
