    // (keeps a balanced spread of gap sizes for future items).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.15;

    // Late in the stream, tighten up: prioritize compacting residuals.
    let progress = step_index as f64 / total_items.max(1) as f64;
