    let density_gap = (mean_residual - residual_f) / cap_f;
    score -= density_gap * (30.0 + 12.0 * progress);

    // Last-chance bin: strongly favor using the only fitting bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    } else if fitting_bins_count > 0 && fitting_bins_count <= 3 && bin_residual != bin_capacity {
        score -= (4.0 - fitting_bins_count as f64) * 5.5;
    }

    // New-bin candidate logic
    if bin_residual == bin_capacity {
        if next_item_size > 0 && (item_size + next_item_size) == bin_capacity {
            score -= 46.0;
        } else if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score -= 10.0;
        } else {
            let waste_factor = ((mean_residual / cap_f) - 0.1).max(0.0);
            let none_fit_next = next_item_size > 0 && post_residual < next_item_size;
            let open_bonus = if none_fit_next { -8.0 } else { 0.0 };
            let tight_open_bins = next_item_size > 0 && item_size as f64 > mean_residual * 2.0;
            let tight_bonus = if tight_open_bins { -6.0 } else { 0.0 };
            score += 26.0 + 0.2 * open_bins_count as f64 + waste_factor * 22.0 + open_bonus + tight_bonus;
        }
        score += progress * 20.0;
    }

    // Late-stream consolidation: penalize leaving large residuals as stream progresses
    score += progress * progress * 14.0 * (residual_f / cap_f);

    // Small tie-break: prefer filling bins with higher current fill
    score -= (bin_residual as f64 / cap_f) * 5.0;

    // Dead-space guard: penalize residuals too small for typical upcoming items
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 0.40;
    }

    // Fragmentation guard: residuals below half of next item are nearly dead
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size / 2 {
        score += 10.0;
    }

    // Perfect-completion bonus: bin becomes exactly full after this item
    if post_residual == 0 && bin_residual != bin_capacity {
        score -= 17.0;
        if next_item_size > 0 && bin_residual % next_item_size == 0 {
            score -= 5.0;
        }
    }

    // Near-perfect fill bonus: residuals up to 6 are almost full
    if post_residual > 0 && post_residual <= 6 && bin_residual != bin_capacity {
        if post_residual <= 3 {
            score -= 10.0 + (4 - post_residual) as f64 * 3.0;
        } else {
            score -= 12.0 - (post_residual - 3) as f64 * 2.0;
        }
    }

    // Residual-vs-mean dead-space ratio: wasteful bins penalized softly
    if residual_f > mean_residual {
        score += (residual_f - mean_residual) * 0.14;
    }

    // Harmony bonus — item exactly halves the residual (classic pairing)
    if bin_residual > item_size && (bin_residual - item_size) == item_size {
        score -= 9.0;
    }

    // Escalated dead-space penalty for very small unusable residuals
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size.min(20) {
        score += 5.0;
    }

    // Combined fine-grained fit + lookahead coupling
    if next_item_size > 0 && post_residual >= next_item_size {
        let remainder = post_residual - next_item_size;
        if remainder > 0 && remainder < next_item_size {
            score += 2.0;
        }
        score -= ((next_item_size * 4) as f64 / (residual_f + 1.0)) * 3.0;
    }

    // Dead-space ratio guard using mean residual as reference scale
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        let dead_ratio = post_residual as f64 / next_item_size as f64;
        score += (1.0 - dead_ratio) * 8.0;
        if residual_f > mean_residual {
            score += (residual_f - mean_residual) * 0.22 * (0.5 + progress);
        }
    }

    // Triple-chain lookahead — versatile reservoir early in the stream
    if next_item_size > 0 && post_residual >= 3 * next_item_size && progress < 0.6 {
        score -= 4.0;
    }

    // Salvageability coupling — residual reusable by a wide range of items
    if post_residual > 0 && progress < 0.9 {
        let usable = (post_residual.min(100)) as f64 / 100.0;
        score -= usable * (1.0 - progress) * 6.0;
    }

    // Endgame tightening — prefer chain-fillable bins near stream end
    if progress > 0.7 && post_residual > 0 {
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 5.0 * progress;
        } else {
            score += 6.0 * (residual_f / cap_f) * progress;
        }
    }

    // Mid-stream salvage threshold — keep versatile bins open when several compete
    if next_item_size > 0 && post_residual >= next_item_size + 5 && fitting_bins_count > 2 && progress < 0.5 {
        score -= 3.5;
    }

    // Dead-space floor penalty scaled by remaining stream length
    if post_residual > 0 && post_residual < 8 && progress < 0.85 {
        score += (8 - post_residual) as f64 * (1.0 - progress) * 2.2;
    }

    // Reward residuals in the "highly reusable band" around mean residual
    if post_residual > 0 {
        let band = ((residual_f - mean_residual).abs() / cap_f).min(1.0);
        score -= (1.0 - band) * 4.0 * (1.0 - progress);
    }

    // Fine-grained fit with lookahead anticipation — residual absorbs next item
    // and leaves a small remainder itself reusable by the following stream
    if next_item_size > 0 && post_residual > next_item_size {
        let remainder = post_residual - next_item_size;
        if remainder >= 1 && remainder <= 10 && progress > 0.4 {
            score -= (11 - remainder) as f64 * 0.8 * progress;
        }
        if remainder >= next_item_size / 2 && remainder < next_item_size && progress < 0.7 {
            score -= 3.0;
        }
    }

    // Penalize opening new bins when a decent (>= 60% of next item) fit exists
    if bin_residual == bin_capacity && next_item_size > 0 && fitting_bins_count > 0 {
        if post_residual >= (next_item_size as f64 * 0.6) as u32 && post_residual < next_item_size {
            score += 6.0 * (1.0 - progress);
        }
        // Extra: never open a bin when an exact next-item fit exists in an open bin
        if post_residual == next_item_size {
            score += 40.0;
        }
    }

    // Dead-space ratio sweep: strongly penalize residuals just under the next item
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        let dead_frac = post_residual as f64 / next_item_size as f64;
        if dead_frac > 0.75 {
            score += (dead_frac - 0.75) * 20.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls into a "usable"
    // residue class (multiples of 10, or >= next item) are rewarded.
    let class = post_residual / 10;
    match class {
        0 => score += 60.0,              // dead space <= 9: nearly unusable
        1 => score -= 5.0,               // 10-19: fits smallest items
        2 => score -= 12.0,              // 20-29
        3 => score -= 18.0,              // 30-39
        4 => score -= 22.0,              // 40-49
        _ => score -= 25.0,              // 50+: very flexible
    }

    // Exact modulo-10 alignment bonus (harmonic with typical item granularity).
    if post_residual % 10 == 0 {
        score -= 8.0;
    }

    // Reward if the next item fits into post_residual (lookahead chaining).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= (next_item_size.min(40) as f64) * 0.9;
    } else if next_item_size > 0 {
        // Penalize leaving a gap that just barely misses the next item.
        score += (next_item_size - post_residual) as f64 * 0.35;
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate: penalize opening a bin unless the item is large and
    // would leave a well-structured residual in an existing bin.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let waste_penalty = (bin_capacity - item_size) as f64 * 0.55;
        score = waste_penalty + progress * 10.0;
        // Opening a bin is attractive for big items (good long-term residual).
        if item_size >= 50 {
            score -= 20.0;
        }
        // If existing bins are fragmented, a fresh bin is more attractive.
        score -= mean_residual * 0.1;
        // Many open bins: discourage further sprawl.
        score += open_bins_count as f64 * 2.0;
    }

    // Tight fits are excellent: minimal post_residual relative to item size.
    let tightness = post_residual as f64 / (item_size.max(1) as f64);
    score -= (1.0 - tightness.min(1.0)) * 15.0;

    // Prefer filling bins that are already mostly full (best-fit flavor).
    score -= (bin_capacity - bin_residual) as f64 * 0.12;

    score
}

