pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward exact fits strongly.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Strict dead-space avoidance: penalize small unusable gaps.
    // A gap is "dead" if no plausible future item (1..=100) can be ruled in/out,
    // but especially gaps below the minimum item size are pure waste.
    if post_residual > 0 {
        // Small gaps (< 10) are almost surely dead space.
        if post_residual < 10 {
            score += 120.0;
        }
        // Gaps that cannot fit the next item are temporarily dead.
        if next_item_size > 0 && post_residual < next_item_size {
            score += 40.0;
        }
        // Nonlinear penalty: gaps just above half capacity waste more potential.
        if post_residual > bin_capacity as f64 * 0.5 {
            // large residual is fine; slight reward to keep big gaps alive
            score -= 5.0;
        } else {
            // mid/small gaps: quadratic dead-space penalty
            let g = post_residual as f64;
            score += 0.15 * (10.0 - g).max(0.0);
        }
    }

    // Last-chance pressure: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // Open-bins pressure: discourage spreading when many bins are open.
    score += open_bins_count as f64 * 1.5;

    // New-bin candidate handling: only attractive when open bins are crowded or fit is poor.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Base penalty so new bins are used only when necessary.
        score += 150.0;
        // Reduce penalty when open bins have little room on average.
        score -= (mean_residual / bin_capacity as f64) * 100.0;
        // If no open bin fits besides this candidate, opening a new bin is fine.
        if fitting_bins_count == 1 {
            score -= 140.0;
        }
        // Late in the stream, prefer consolidation slightly less.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= progress * 10.0;
    }

    // Slight preference for tighter bins overall.
    score += (bin_residual as f64 - post_residual as f64) * 0.01;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let nxt = next_item_size as f64;
    let res_f = bin_residual as f64;

    // Base: quadratic penalty on post residual, progress-modulated
    let mut score = norm_pr * (1.0 + 0.8 * norm_pr) * (1.0 + 0.5 * progress);

    // Exact chain fill: post residual perfectly absorbs next item
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 70.0;
        } else if post_residual > next_item_size {
            let fit_ratio = (pr / nxt).min(3.0);
            let smooth = fit_ratio / (1.0 + fit_ratio);
            score -= 2.0 * smooth * (1.0 - progress * 0.5);
            let slack = (post_residual - next_item_size) as f64;
            // Two-chain lookahead: residual can absorb next item twice
            if post_residual >= 2 * next_item_size && pr <= cap * 0.5 {
                score -= 7.0;
            }
            // Tight chain fill discrimination
            if slack > 0.0 && slack < nxt * 0.15 {
                score -= 6.0 * (1.0 - slack / (nxt * 0.15));
            }
            // Complement harmony: pair hits capacity or half capacity
            if pr + nxt == cap {
                score -= 16.0;
            } else if pr + nxt == cap * 0.5 {
                score -= 9.0;
            }
            // Divisibility: residual a clean multiple of next item promises exact fills
            if post_residual % next_item_size == 0 {
                score -= 5.0;
            }
        } else {
            // Dead space: next item cannot fit into post residual
            let gap = nxt - pr;
            score += gap * 0.55;
            // Stranded-capacity scaled penalty
            score += (gap / cap) * 30.0 * (0.4 + 0.6 * progress);
            if post_residual > 0 && post_residual < next_item_size / 2 {
                score += 8.0;
            }
        }
    }

    // Last-chance bonus: few fitting bins -> strongly favor using this bin
    if fitting_bins_count <= 1 && bin_residual != bin_capacity {
        score -= 25.0;
    } else if fitting_bins_count <= 3 && bin_residual != bin_capacity {
        score -= (4.0 - fitting_bins_count as f64) * 4.5;
    } else {
        score += 0.1 * (fitting_bins_count as f64).ln();
    }

    // Density coupling: prefer bins tighter than mean residual
    let density_gap = (mean_residual - pr) / cap;
    score -= density_gap * (22.0 + 12.0 * progress);

    // Tightness preference
    let tightness = 1.0 - res_f / cap;
    score += 0.3 * tightness * (1.0 - progress);

    // Perfect completion: bin becomes exactly full
    if post_residual == 0 && bin_residual != bin_capacity {
        score -= 18.0;
        if next_item_size > 0 && bin_residual % next_item_size == 0 {
            score -= 4.0;
        }
    }

    // Near-perfect fill bonus
    if post_residual > 0 && post_residual <= 6 && bin_residual != bin_capacity {
        score -= 9.0 + (6 - post_residual) as f64;
    }

    // New-bin candidate logic: only open when justified
    if bin_residual == bin_capacity {
        if next_item_size > 0 && (item_size + next_item_size) == bin_capacity {
            score -= 44.0;
        } else if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score -= 9.0;
        } else {
            let none_fit_next = next_item_size > 0 && post_residual < next_item_size;
            let mut open_pen = 4.0 + 2.0 * (1.0 - progress) + 0.2 * open_bins_count as f64;
            if none_fit_next {
                open_pen -= 7.0;
            }
            score += open_pen;
        }
        // Late-stream: opening bins is almost always wasteful
        if progress > 0.85 {
            score += 200.0 * (progress - 0.85);
        }
        score += progress * 14.0;
