    if next_item_size > 0 && post_residual > next_item_size {
        let remainder = post_residual - next_item_size;
        if remainder >= 1 && remainder <= 10 && progress > 0.4 {
            score -= (11 - remainder) as f64 * 0.8 * progress;
        }
        if remainder >= next_item_size / 2 && remainder < next_item_size && progress < 0.7 {
            score -= 3.0;
        }
    }

    // Best-fit discrimination among competing fitting bins
    if fitting_bins_count > 1 && post_residual > 0 && bin_residual != bin_capacity {
        let tight = 1.0 - (post_residual as f64 / cap_f);
        score -= tight * 8.0 / fitting_bins_count as f64;
    }

    // Residual divisibility — clean multiple of next item promises exact fills
    if next_item_size > 1 && post_residual > 0 && post_residual % next_item_size == 0 && post_residual >= next_item_size {
