        } else if fill < 0.5 {
            score += (0.5 - fill) * 16.0;
        }
    }

    // Inter-item gap coupling
    if next_item_size > 0 && fitting_bins_count <= 2 && post_residual >= next_item_size {
        let margin = (post_residual - next_item_size) as f64;
        score -= margin.min(30.0) * 0.35 * (1.0 - progress);
    }

    // NEW MUTATION: dead-space escape valve — if the dead residual can be
    // eliminated by a *later* known quantity (next item fits after this one
    // fills the bin exactly), treat the dead space as recoverable rather
    // than stranded. Scaled by remaining stream so early flexibility counts.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        let fill_after = (bin_residual + item_size) as f64;
        if fill_after >= cap_f - 1e-6 {
            // Item exactly closes the bin: dead space is irrelevant
            score -= 12.0 * (1.0 - progress);
        } else {
            // Dead residual as fraction of capacity — smaller absolute waste
            // deserves a milder penalty than the linear guards above.
            let waste_frac = post_residual as f64 / cap_f;
            score -= waste_frac * 18.0 * (1.0 - progress);
        }
    }

    // NEW MUTATION: dual-fit discrimination — when several bins can host the
    // next item too, prefer the one whose post-fit slack stays most reusable
    // (slack >= next item keeps the chain alive two steps ahead).
    if next_item_size > 0 && post_residual > next_item_size && fitting_bins_count >= 2 {
        let slack2 = post_residual - next_item_size;
        if slack2 >= next_item_size {
            score -= 2.5 + (1.0 - progress) * 2.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (small post_residual relative to capacity).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // Penalize dead space: residuals too small to hold typical items.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // Lookahead: if the next item fits exactly in the post_residual, reward heavily.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size <= post_residual {
            score -= 8.0 * (next_item_size as f64) / (post_residual as f64);
        } else {
            // Next item cannot use this residual; penalize proportionally wasted space.
            score += 0.15 * (post_residual as f64);
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // Time horizon: early in the stream, encourage consolidation; later, be pickier.
    let progress = (step_index as f64) / (total_items.max(1) as f64);
    score -= (1.0 - progress) * 5.0 * (item_size as f64) / (bin_capacity as f64);

    // Global state coupling: when many open bins with high mean residual exist,
    // prefer filling bins rather than opening new ones.
    if open_bins_count > 0 {
        score -= 0.05 * (mean_residual / (bin_capacity as f64)) * (open_bins_count as f64).ln();
    }

    // New-bin candidate handling: only attractive if no open bin fits well.
    if bin_residual == bin_capacity {
        let base_penalty = 15.0 + 0.3 * (open_bins_count as f64);
        score += base_penalty;
        if fitting_bins_count == 0 {
            score -= 100.0; // no alternative: new bin is fine
        } else if post_residual as f64 > 0.5 * (bin_capacity as f64) {
            score += 10.0; // item is small; avoid wasting a fresh bin
        }
    }

    // Mild penalty for leaving very large residuals untouched when item is tiny.
    if (item_size as f64) < 0.2 * (bin_capacity as f64) && post_residual as f64 > 0.7 * (bin_capacity as f64) {
        score += 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
