    // plus the next item would exactly consume the bin, this is the strongest
    // possible placement; scale reward by how close we are to that state.
    if next_item_size > 0 && bin_residual >= item_size + next_item_size {
        let over = bin_residual - (item_size + next_item_size);
        if over == 0 {
            score -= 22.0;
        } else if over <= 4 {
            score -= (5 - over) as f64 * 3.0;
