    }

    // NEW MUTATION: mean-residual anchored new-bin suppression — when the mean
    // residual is large, opening bins is cheap; when tight, force compaction.
    if bin_residual == bin_capacity && mean_residual / cap_f < 0.08 {
        score += 9.0 * (1.0 - mean_residual / (cap_f * 0.08));
