            if post_residual >= 2 * next_item_size && pr <= cap * 0.5 {
                score -= 7.0;
            }
            // Triple-chain lookahead — versatile reservoir early in the stream
            if post_residual >= 3 * next_item_size && progress < 0.6 {
                score -= 4.0;
            }
            // Complement harmony: pair hits capacity or half capacity
            if pr + nxt == cap {
                score -= 18.0;
            } else if pr + nxt == cap * 0.5 {
                score -= 10.0;
            }
            // Exact-fill cascade — item + next item nearly consumes post_residual
            if slack <= item_size.min(next_item_size) as f64 {
                score -= 4.0;
            }
        } else {
            // Dead space: next item cannot fit into post residual
            let gap = nxt - pr;
            score += gap * 0.75;
            if post_residual > 0 && post_residual < next_item_size / 2 {
                score += 10.0;
            }
            // Dead-space ratio guard using mean residual as reference scale
            let dead_ratio = pr / nxt;
            score += (1.0 - dead_ratio) * 8.0;
            // Stranded potential scaled by progress
            score += (gap / cap) * 30.0 * (0.4 + 0.6 * progress);
            // Fill-level vs dead-space trade
            let fill = bin_residual as f64 / cap;
            if fill > 0.75 {
                score -= (fill - 0.75) * 20.0;
            } else if fill < 0.5 {
                score += (0.5 - fill) * 16.0;
            }
        }
    }

    // Last-chance bonus: few fitting bins -> strongly favor using this bin
    if fitting_bins_count <= 1 && bin_residual != bin_capacity {
        score -= 30.0;
    } else if fitting_bins_count <= 3 && bin_residual != bin_capacity {
        score -= (4.0 - fitting_bins_count as f64) * 5.5;
    } else {
        score += 0.1 * (fitting_bins_count as f64).ln();
    }

    // Inter-item gap coupling: preserve flexible bins when few compete
    if next_item_size > 0 && fitting_bins_count <= 2 && post_residual >= next_item_size {
        let margin = (post_residual - next_item_size) as f64;
        score -= margin.min(30.0) * 0.35 * (1.0 - progress);
    }

    // Density coupling: prefer bins tighter than mean residual
    let density_gap = (mean_residual - pr) / cap;
    score -= density_gap * (24.0 + 12.0 * progress);

    // Slight preference for tighter bins overall
    let tightness = 1.0 - (bin_residual as f64) / cap;
    score += 0.3 * tightness * (1.0 - progress);
    score -= (bin_residual as f64 / cap) * 5.0;

    // Perfect completion: bin becomes exactly full
    if post_residual == 0 && bin_residual != bin_capacity {
        score -= 17.0;
        if next_item_size > 0 && bin_residual % next_item_size == 0 {
            score -= 5.0;
        }
    }

    // Near-perfect fill bonus
    if post_residual > 0 && post_residual <= 6 && bin_residual != bin_capacity {
        if post_residual <= 3 {
            score -= 10.0 + (4 - post_residual) as f64 * 3.0;
        } else {
            score -= 12.0 - (post_residual - 3) as f64 * 2.0;
        }
    }

    // New-bin candidate logic: only open when justified
    if bin_residual == bin_capacity {
        if next_item_size > 0 && (item_size + next_item_size) == bin_capacity {
            score -= 46.0;
        } else if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score -= 10.0;
        } else {
            let none_fit_next = next_item_size > 0 && post_residual < next_item_size;
            let mut open_pen = 26.0 + 0.2 * open_bins_count as f64 + 2.0 * (1.0 - progress);
            if none_fit_next {
                open_pen -= 8.0;
            }
            score += open_pen;
        }
        score += progress * 20.0;
        // New-bin restraint when a >=90% fill is available
        if next_item_size > 0 && post_residual > 0 && post_residual <= bin_capacity / 10 {
            score += 14.0;
        }
        if progress > 0.85 {
            score += 12.0 * (progress - 0.85) * 20.0;
        }
    }

    // Late-stream consolidation: penalize large residuals as stream progresses
    score += progress * progress * 14.0 * norm_pr;

    // Salvageability: residual reusable by wide range of items
    if post_residual > 0 && progress < 0.9 {
        let usable = (post_residual.min(100)) as f64 / 100.0;
        score -= usable * (1.0 - progress) * 6.0;
    }

    // Endgame tightening
    if progress > 0.7 && post_residual > 0 {
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 5.0 * progress;
        } else {
            score += 6.0 * norm_pr * progress;
        }
    }

    // Harmony bonus: item exactly halves the residual
    if bin_residual > item_size && (bin_residual - item_size) == item_size {
        score -= 9.0;
    }

    // Best-fit discrimination among fitting bins — tightest placement rewarded
    if fitting_bins_count > 1 && post_residual > 0 {
        let tight = 1.0 - (post_residual as f64 / cap);
        score -= tight * 8.0 / fitting_bins_count as f64;
    }

    // Residual divisibility — clean multiple of the next item promises exact fills
    if next_item_size > 1 && post_residual > 0 && post_residual % next_item_size == 0 && post_residual >= next_item_size {
        score -= 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: capacity divided into 10 classes of 10.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let class = (post / 10.0).floor().min(9.0);

    // Perfect fit is supreme.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Dead-space penalty: residuals below the minimum item size (1) are useless;
    // residuals in the "awkward zone" (1..=10) waste capacity.
    if post_residual > 0 && post_residual <= 10 {
        score += 25.0 - post as f64;
    }

    // Harmonic class reward: bins whose post residual is a multiple of 10
    // (aligned with class boundaries) leave modularly reusable space.
    if post_residual % 10 == 0 {
        score -= 8.0;
    } else {
        // Penalize misaligned residuals proportionally to distance from class edge.
        let frac = post % 10.0;
        score += 0.6 * frac;
    }

    // Lookahead coupling: reward bins whose post residual exactly fits the next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0;
        } else if post_residual >= next_item_size {
            let gap = post_residual - next_item_size;
            if gap <= 10 {
                score -= 20.0 - gap as f64;
            }
            score -= 0.3 * (next_item_size as f64);
        } else {
            // Next item won't fit here; penalize more for small leftover class.
            score += 0.4 * (next_item_size as f64) * (1.0 - class / 9.0);
        }
    }

    // Last chance: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
        if post_residual <= 5 {
            score += 30.0; // but avoid near-dead placements if avoidable
        }
    }

    // New-bin candidate handling: empty bin should only win when all open fits are bad.
    if bin_residual == bin_capacity {
        // Base new-bin score: neutral-ish, scaled by stream progress.
        score = cap * 0.6 + 0.5 * (open_bins_count as f64);
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 10.0; // new bin pairs well with a big follower
        }
        if fitting_bins_count == 0 {
            score -= 200.0; // nothing fits, must open
        }
        // Late in stream, prefer closing out open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * progress;
    } else {
        // Open bins: reward tightness relative to mean residual.
        score -= 0.15 * (mean_residual - post).max(0.0);
        // Fewer open bins => tighter packing preferred.
        score += 0.2 * (open_bins_count as f64);
    }

    score
}

