    // Open-bins pressure: mildly discourage spreading across many bins,
    // but encourage using existing bins when few fit options remain.
    score += (open_bins_count as f64) * 1.5;

    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        // Last chance bin: strong reward to avoid opening a new bin.
        score -= 50.0;
    }

    // New-bin candidate handling: only prefer a fresh bin if this bin would
    // create severe dead space and other options are plentiful.
    if bin_residual == bin_capacity {
        score += 30.0; // default mild penalty for opening a new bin
        if post_residual > 0 && post_residual < 20 && fitting_bins_count > 2 {
            score -= 55.0; // all fits are bad; a fresh bin is better
        }
