    // leftover is a tiny dead sliver clearly preferable to mid-full bins with
    // the same sliver.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        let dead_frac = post_residual as f64 / cap_f;
        let dead_cost = dead_frac * dead_frac * 120.0 * (0.5 + progress);
        score += dead_cost;
        // If some OTHER open bin could absorb the next item, this bin's dead
        // sliver is pure loss — escalate.
        if fitting_bins_count > 1 {
            score += dead_cost * 0.25;
        }
    }

    // NEW MUTATION: residual reuse probability — estimate how likely a future
    // item (approximated by next_item_size scale) can consume the leftover
    // residual; reward residuals that are multiples of common small sizes.
    if post_residual > 0 && post_residual < 40 && progress < 0.8 {
