    if next_item_size > 0 && fitting_bins_count <= 2 && post_residual >= next_item_size {
        let margin = (post_residual - next_item_size) as f64;
        score -= margin.min(30.0) * 0.35 * (1.0 - progress);
    }

    // NEW MUTATION: dead-space refund for near-full bins — when the bin is >85%
    // full and the dead residual is tiny (<8), the waste is bounded; refund part
    // of the accumulated dead-space penalties proportionally to fill level.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        let fill = bin_residual as f64 / cap_f;
        if fill > 0.85 && post_residual < 8 {
            score -= (fill - 0.85) * 60.0 * (1.0 - post_residual as f64 / 8.0);
        }
    }

    // NEW MUTATION: two-item lookahead wedge — a residual that can host the next
    // item AND still leave >= item_size (for the item after) is a strong chain
    // anchor; reward scaled by how early in the stream it appears.
    if next_item_size > 0 && post_residual >= next_item_size + item_size
        && post_residual < next_item_size + 2 * item_size {
        score -= 7.0 * (1.0 - progress) + 3.0;
    }

    // NEW MUTATION: mean-residual parity targeting — bins whose post_residual is
    // close to the mean residual are statistically reusable by the stream's
    // typical sizes; reward closeness quadratically.
    if post_residual > 0 {
        let dist = (residual_f - mean_residual).abs();
        if dist < cap_f * 0.1 {
            score -= (1.0 - dist / (cap_f * 0.1)) * 4.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
