    let mut score = pr * (1.0 + 0.5 * pr_norm);

    // Polynomial coupling of post_residual with stream progress:
    // later in the stream, larger post_residuals are penalized more heavily.
    let prog_poly = progress * progress * (3.0 - 2.0 * progress); // smoothstep
    score += pr_norm * pr_norm * 40.0 * (0.5 + prog_poly);

    // Lookahead interaction: reward residual that can hold the next item,
    // scaled non-linearly by progress.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            score -= 6.0 * (1.0 - pr_norm * (nxt / cap)) * (0.5 + 0.5 * progress);
        } else {
            score += 4.0 * (nxt - pr) / cap;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening a new bin, more so early and when
    // open bins could fit; the penalty decays smoothly with progress.
    if bin_residual == bin_capacity {
        let open_penalty = 12.0 + 0.3 * open_bins_count as f64;
        score += open_penalty * (1.0 - 0.4 * progress);
    }

    // Mild mean-residual coupling: keep residuals balanced across bins.
    score += 0.05 * (pr - mean_residual).abs();

    score
}

