    let r10 = (post_residual % 10) as f64;
    score -= 0.6 * r10; // leftover with high residue mod 10 is more reusable

    // Classify post_residual by integer division buckets (harmonic fractions of capacity)
    let half = bin_capacity / 2;
    let third = bin_capacity / 3;
    let quarter = bin_capacity / 4;
    if post_residual >= half {
        score += 8.0; // leaving half a bin is wasteful unless justified
    } else if post_residual >= third {
        score += 3.0;
    } else if post_residual >= quarter {
        score -= 2.0; // quarter-leftover is a useful harmonic class
    }

    // Lookahead coupling: if next item fits exactly in post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size <= post_residual {
            score -= 6.0;
        } else {
            // next item won't fit here; penalize proportionally to mismatch
            let mismatch = (next_item_size - post_residual) as f64;
            score += 0.15 * mismatch;
            // harmonic class of next item vs post residual via integer division
            if next_item_size / 2 >= post_residual {
                score += 4.0;
            }
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: empty bin should only win when alternatives are bad
    if bin_residual == bin_capacity {
        score += 55.0 + 0.3 * open_bins_count as f64;
        // but if stream is early, opening bins is cheap
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 20.0 * (1.0 - progress);
    }

    // Prefer tighter bins relative to current mean residual
    score -= 0.2 * (mean_residual - post_residual as f64);

    // Small tie-breaker favoring exact fills of common harmonic classes
    if post_residual % 25 == 0 && post_residual > 0 {
        score -= 3.0;
    }
    if post_residual == 0 {
        score -= 50.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let residual_f = post_residual as f64;
    let cap_f = bin_capacity as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = residual_f;

    // Exact 2-step chain: post_residual perfectly absorbs the next item
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 96.0;
        } else if post_residual > next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            let tightness = 1.0 - (slack / cap_f).min(1.0);
            score -= 14.0 + slack * 0.3 + tightness * 12.0;
            if (slack as u32) >= next_item_size {
                score -= 11.0;
                if slack >= 2.0 * next_item_size as f64 {
                    score -= 7.0;
                }
            }
            if slack >= next_item_size as f64 && slack <= 25.0 {
                score -= (25.0 - slack) * 0.55;
            }
            if slack > 0.0 && slack < (next_item_size as f64) * 0.15 && bin_residual as f64 >= cap_f * 0.5 {
                score -= 6.0 * (1.0 - slack / ((next_item_size as f64) * 0.15));
            }
            if post_residual >= 2 * next_item_size && post_residual as f64 <= cap_f * 0.5 {
                score -= 7.0;
            }
        } else if post_residual > 0 {
            let gap = (next_item_size - post_residual) as f64;
            score += gap * 0.95;
        }
    }

    // Complement harmony
    if next_item_size > 0 && post_residual > next_item_size {
        let pair = residual_f + next_item_size as f64;
        if pair == cap_f {
            score -= 18.0;
        } else if pair == cap_f * 0.5 {
            score -= 10.0;
        }
    }

    // Density coupling
    let density_gap = (mean_residual - residual_f) / cap_f;
    score -= density_gap * (30.0 + 12.0 * progress);

    // Last-chance bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    } else if fitting_bins_count > 0 && fitting_bins_count <= 3 && bin_residual != bin_capacity {
        score -= (4.0 - fitting_bins_count as f64) * 5.5;
    }

    // New-bin candidate logic
    if bin_residual == bin_capacity {
        if next_item_size > 0 && (item_size + next_item_size) == bin_capacity {
            score -= 46.0;
        } else if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score -= 10.0;
        } else {
            let waste_factor = ((mean_residual / cap_f) - 0.1).max(0.0);
            let none_fit_next = next_item_size > 0 && post_residual < next_item_size;
            let open_bonus = if none_fit_next { -8.0 } else { 0.0 };
            score += 26.0 + 0.2 * open_bins_count as f64 + waste_factor * 22.0 + open_bonus;
        }
        score += progress * 20.0;
        if next_item_size > 0 && post_residual > 0 && post_residual <= bin_capacity / 10 {
            score += 14.0;
        }
        if progress > 0.85 {
            score += 12.0 * (progress - 0.85) * 20.0;
        }
        // MUTATION: restrain new-bin opening when the current bin's residual
        // exceeds next item by a small margin (cheap continuation available).
        if next_item_size > 0 && post_residual >= next_item_size
            && post_residual - next_item_size <= 12 {
            score += 6.0;
        }
    }

    // Late-stream consolidation
    score += progress * progress * 14.0 * (residual_f / cap_f);

    // Small tie-break
    score -= (bin_residual as f64 / cap_f) * 5.0;

    // Dead-space guard
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 0.40;
    }

    // Fragmentation guard
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size / 2 {
        score += 10.0;
    }

    // Perfect-completion bonus
    if post_residual == 0 && bin_residual != bin_capacity {
        score -= 17.0;
        if next_item_size > 0 && bin_residual % next_item_size == 0 {
            score -= 5.0;
        }
    }

    // Near-perfect fill bonus
    if post_residual > 0 && post_residual <= 6 && bin_residual != bin_capacity {
        if post_residual <= 3 {
            score -= 10.0 + (4 - post_residual) as f64 * 3.0;
        } else {
            score -= 12.0 - (post_residual - 3) as f64 * 2.0;
        }
    }

    // Residual-vs-mean dead-space ratio
    if residual_f > mean_residual {
        score += (residual_f - mean_residual) * 0.14;
    }

    // Harmony bonus
    if bin_residual > item_size && (bin_residual - item_size) == item_size {
