        let tight = 1.0 - (post_residual as f64 / cap_f);
        score -= tight * 8.0 / fitting_bins_count as f64;
    }

    // Residual divisibility
    if next_item_size > 1 && post_residual > 0 && post_residual % next_item_size == 0 && post_residual >= next_item_size {
        score -= 6.0;
    }

    // Fill-level vs. dead-space trade
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        let fill = bin_residual as f64 / cap_f;
        if fill > 0.75 {
            score -= (fill - 0.75) * 20.0;
        } else if fill < 0.5 {
            score += (0.5 - fill) * 16.0;
        }
    }

    // Inter-item gap coupling
    if next_item_size > 0 && fitting_bins_count <= 2 && post_residual >= next_item_size {
        let margin = (post_residual - next_item_size) as f64;
        score -= margin.min(30.0) * 0.35 * (1.0 - progress);
    }

    // MUTATION: dead-residual recoverability — a stranded residual is less costly
    // if it could still absorb a typical item later; scale by how close it is
    // to the next item size from below (near-miss residuals are salvageable).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        let near_miss = post_residual as f64 / next_item_size as f64;
        if near_miss > 0.7 {
            score -= (near_miss - 0.7) * 14.0 * (1.0 - progress);
        }
    }

    // MUTATION: two-step exact chain — post_residual minus next item leaves a
    // residual that exactly equals a plausible future fit (half-capacity anchor).
    if next_item_size > 0 && post_residual > next_item_size {
        let after = post_residual - next_item_size;
        if after == bin_capacity / 2 || after == next_item_size {
            score -= 8.0 * (1.0 - progress);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let nxt = next_item_size as f64;
    let fill = bin_residual as f64 / cap;

    // Base: quadratic penalty on post residual, progress-modulated
    let mut score = norm_pr * (1.0 + 0.8 * norm_pr) * (1.0 + 0.5 * progress);

    // Exact chain fill: post residual perfectly absorbs next item
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 96.0;
        } else if post_residual > next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            let tightness = 1.0 - (slack / cap).min(1.0);
            score -= 14.0 + slack * 0.3 + tightness * 12.0;
            if (slack as u32) >= next_item_size {
                score -= 11.0;
                if slack >= 2.0 * nxt {
                    score -= 7.0;
                }
            }
            // Small viable slack is a prime chain candidate — reward quadratically
            if slack >= nxt && slack <= 25.0 {
                score -= (25.0 - slack) * 0.55;
            }
            if slack > 0.0 && slack < nxt * 0.15 && bin_residual as f64 >= cap * 0.5 {
                score -= 6.0 * (1.0 - slack / (nxt * 0.15));
            }
            // Two-chain lookahead
            if post_residual >= 2 * next_item_size && pr <= cap * 0.5 {
                score -= 7.0;
            }
            // Triple-chain lookahead early in stream
            if post_residual >= 3 * next_item_size && progress < 0.6 {
                score -= 4.0;
            }
            // Complement harmony: pair hits capacity or half capacity
            if pr + nxt == cap {
                score -= 18.0;
            } else if pr + nxt == cap * 0.5 {
                score -= 10.0;
            }
            // Exact-fill cascade: item + next nearly consume post residual
            if (post_residual - next_item_size) <= item_size.min(next_item_size) {
                score -= 4.0;
            }
            // Residual divisibility promises exact fills
            if next_item_size > 1 && post_residual % next_item_size == 0 {
                score -= 6.0;
            }
        } else {
            // Dead space: next item cannot fit into post residual
            let gap = nxt - pr;
            score += gap * 0.95;
            if post_residual > 0 && post_residual < next_item_size / 2 {
                score += 10.0;
            }
            let dead_ratio = pr / nxt;
            score += (1.0 - dead_ratio) * 8.0;
            let stranded = (nxt - pr) / cap;
            score += stranded * 30.0 * (0.4 + 0.6 * progress);
            // Fill-level vs dead-space trade
            if fill > 0.75 {
                score -= (fill - 0.75) * 20.0;
            } else if fill < 0.5 {
                score += (0.5 - fill) * 16.0;
            }
        }
    }

    // Last-chance bonus: few fitting bins -> strongly favor using this bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    } else if fitting_bins_count <= 3 && fitting_bins_count > 0 && bin_residual != bin_capacity {
        score -= (4.0 - fitting_bins_count as f64) * 5.5;
    } else {
        score += 0.1 * (fitting_bins_count as f64).ln();
    }

    // Best-fit discrimination among fitting bins
    if fitting_bins_count > 1 && post_residual > 0 {
        let tight = 1.0 - (pr / cap);
        score -= tight * 8.0 / fitting_bins_count as f64;
    }

    // Mid-stream salvage threshold
    if next_item_size > 0 && post_residual >= next_item_size + 5 && fitting_bins_count > 2 && progress < 0.5 {
        score -= 3.5;
    }

    // Inter-item gap coupling: preserve flexible bins when few compete
    if next_item_size > 0 && fitting_bins_count <= 2 && post_residual >= next_item_size {
        let margin = (post_residual - next_item_size) as f64;
        score -= margin.min(30.0) * 0.35 * (1.0 - progress);
    }

    // Density coupling: prefer bins tighter than mean residual
    let density_gap = (mean_residual - pr) / cap;
    score -= density_gap * (30.0 + 12.0 * progress);

    // Slight preference for tighter bins overall
    score -= fill * 5.0;

    // Perfect completion: bin becomes exactly full
    if post_residual == 0 && bin_residual != bin_capacity {
        score -= 17.0;
        if next_item_size > 0 && bin_residual % next_item_size == 0 {
            score -= 5.0;
        }
    }

    // Near-perfect fill bonus
    if post_residual > 0 && post_residual <= 6 && bin_residual != bin_capacity {
        if post_residual <= 3 {
            score -= 10.0 + (4 - post_residual) as f64 * 3.0;
        } else {
            score -= 12.0 - (post_residual - 3) as f64 * 2.0;
        }
    }

    // New-bin candidate logic: only open when justified
    if bin_residual == bin_capacity {
        if next_item_size > 0 && (item_size + next_item_size) == bin_capacity {
            score -= 46.0;
        } else if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score -= 10.0;
        } else {
            let waste_factor = ((mean_residual / cap) - 0.1).max(0.0);
            let none_fit_next = next_item_size > 0 && post_residual < next_item_size;
            let open_bonus = if none_fit_next { -8.0 } else { 0.0 };
            score += 26.0 + 0.2 * open_bins_count as f64 + waste_factor * 22.0 + open_bonus;
        }
        score += progress * 20.0;
        // New-bin restraint when a >=90% fill is available
        if next_item_size > 0 && post_residual > 0 && post_residual <= bin_capacity / 10 {
            score += 14.0;
        }
        if progress > 0.85 {
            score += 12.0 * (progress - 0.85) * 20.0;
        }
    }

    // Late-stream consolidation
    score += progress * progress * 14.0 * norm_pr;

    // Residual-vs-mean dead-space penalty
    if pr > mean_residual {
        score += (pr - mean_residual) * 0.14;
    }

    // Harmony bonus: item exactly halves the residual
    if bin_residual > item_size && (bin_residual - item_size) == item_size {
        score -= 9.0;
    }

    // Salvageability: residual reusable by wide range of items
    if post_residual > 0 && progress < 0.9 {
        let usable = (post_residual.min(100)) as f64 / 100.0;
        score -= usable * (1.0 - progress) * 6.0;
    }

    // Endgame tightening
    if progress > 0.7 && post_residual > 0 {
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 5.0 * progress;
        } else {
            score += 6.0 * norm_pr * progress;
        }
    }

    score
}

