            score += (0.5 - fill) * 16.0;
        }
    }

    // Inter-item gap coupling
    if next_item_size > 0 && fitting_bins_count <= 2 && post_residual >= next_item_size {
        let margin = (post_residual - next_item_size) as f64;
        score -= margin.min(30.0) * 0.35 * (1.0 - progress);
    }

    // NEW MUTATION: dead-space floor calibration — a residual that is "dead" for the
    // next item but still above the mean residual is the worst kind of waste; penalize
    // proportionally to how far it exceeds mean, scaled by remaining stream length.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        let over_mean = (residual_f - mean_residual).max(0.0) / cap_f;
        score += over_mean * 18.0 * (1.0 - progress);
        // But if the dead residual is tiny (<=4), it costs almost nothing — soften.
        if post_residual <= 4 {
            score -= 6.0;
        }
    }

    // NEW MUTATION: dual-chain viability — reward residuals that can host the next
    // item AND still leave room for a mid-sized follow-up (>= 20), since long streams
    // almost surely contain such items. This sharpens chain selection beyond the
    // single-step slack reward.
    if next_item_size > 0 && post_residual >= next_item_size + 20 && progress < 0.75 {
        score -= 3.0 + 3.0 * (1.0 - progress);
    }

    // NEW MUTATION: open-bin pressure — when many bins are open, resist opening yet
    // another unless the current best fit is poor; when few bins are open, opening is
    // cheap. Coupled with mean residual as a global waste signal.
    if bin_residual == bin_capacity {
        let pressure = open_bins_count as f64 / (1.0 + mean_residual / cap_f * 10.0);
        score += pressure * 1.5;
        if next_item_size > 0 && item_size >= next_item_size && item_size + next_item_size > bin_capacity {
            // Item is large and pairs badly with next: opening fresh is reasonable.
            score -= 6.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong base preference for tight fits (low post_residual).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 40.0 * tightness * tightness;

    // Aggressive 2-step lookahead: reward when next item fits the post-residual.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Next item chains perfectly: bonus scaled by how snugly it fits.
            let gap = (post_residual - next_item_size) as f64;
            score -= 30.0 * (1.0 - gap / (bin_capacity as f64));
        } else {
            // Next item won't fit here: penalize leaving a residual that is
            // neither large nor tiny (unusable dead space).
            let dead = post_residual as f64;
            if dead < next_item_size as f64 {
                let waste = (next_item_size as f64 - dead) / (bin_capacity as f64);
                score += 25.0 * waste;
            }
        }
    }

    // Compare against mean residual: bins with more room than average are
    // naturally better targets; bins below average residual are risky.
    score += 0.5 * (mean_residual - bin_residual as f64);

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 {
        score -= 20.0;
    } else if fitting_bins_count > 1 {
        score += 2.0 * (fitting_bins_count as f64 - 1.0);
    }

    // Penalize opening a new bin when the item fits comfortably in this one.
    if bin_residual == bin_capacity {
        score += 15.0 + 0.3 * (open_bins_count as f64);
    } else if post_residual <= 5 {
        // Nearly perfect fill: strong bonus.
        score -= 35.0;
    }

    // Early in the stream, be more willing to consolidate (fewer open bins).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 10.0 * (1.0 - progress) * (open_bins_count as f64 / 20.0).min(1.0);

    score
}

