    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 30.0 * fit_ratio * fit_ratio;

    // Penalize dead space that can't hold typical small items
    if post_residual > 0 && post_residual < 10 {
        score -= 20.0; // perfect-ish fill
    } else if post_residual < 20 {
        score -= 10.0;
    } else if post_residual > 60 {
        score += 8.0; // large unusable gap
    }

    // Lookahead coupling: if next item fits in the post residual, big reward
    if next_item_size > 0 {
        if (post_residual as u32) >= next_item_size {
            score -= 15.0 + 0.2 * next_item_size as f64;
        } else {
