pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Base: prefer minimal post_residual (tight fit).
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: integer division by 10 defines
    // "dead space classes" 0..=9. Class 0 (post_residual < 10) is ideal
    // since no future item (min size 1, but practically >=10) fits.
    let post_class = post_residual / 10;
    let post_mod = post_residual % 10;

    // Reward classes that are unusable (post_residual < 10): no dead space loss.
    if post_class == 0 {
        score -= 15.0;
    }

    // Reward exact class boundaries that match common item sizes
    // (post_residual in {0, 10, 20, ...}) — clean slots for future items.
    if post_mod == 0 && post_residual > 0 {
        score -= 6.0;
    }

    // Harmonic penalty: post_residual just above a multiple of 10 wastes space.
    if post_mod > 0 && post_mod <= 5 {
        score += 4.0 + post_mod as f64;
    }

    // Lookahead coupling: does next_item_size fit into post_residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Reward if the next item fits harmonically (class-compatible).
            let slack = post_residual - next_item_size;
            if slack == 0 {
                score -= 20.0; // perfect chain placement
            } else if slack < 10 {
                score += 3.0; // creates tiny dead space after next item
            } else {
                score -= 8.0;
            }
        } else {
            // Next item won't fit here: mild penalty unless post_residual
            // is already in the unusable class.
            if post_class > 0 {
                score += 5.0;
            }
        }
    }

    // Last-chance logic: if this is the only fitting bin, strongly prefer
    // using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // the item fits poorly everywhere else. Penalize fresh bins mildly so
    // existing bins with decent fits win.
    if bin_residual == bin_capacity {
        // Scale penalty with stream progress: later in the stream, prefer
        // consolidating into open bins even more.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 30.0 + 20.0 * progress;

        // Exception: very large items relative to capacity are fine in new bins.
        if (item_size as f64) > 0.7 * bin_capacity as f64 {
            score -= 20.0;
        }
    }

    // Congestion-aware term: many open bins with high mean residual means
    // fragmentation; prefer bins below mean residual (tighter bins).
    let residual_f = bin_residual as f64;
    if residual_f < mean_residual {
        score -= 3.0;
    } else {
        score += 2.0;
    }

    // Slight preference for bins whose residual is harmonically related
    // to the item size (item divides residual evenly).
    if item_size > 0 && bin_residual % item_size == 0 {
        score -= 5.0;
    }

    score
}

