    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 80.0;
        } else if post_residual > next_item_size {
            let fit_ratio = (pr / nxt).min(3.0);
            let smooth = fit_ratio / (1.0 + fit_ratio);
            score -= 2.0 * smooth * (1.0 - progress * 0.5);
            let slack = (post_residual - next_item_size) as f64;
            // Two-chain lookahead: residual can absorb next item twice
            if post_residual >= 2 * next_item_size && pr <= cap * 0.5 {
                score -= 7.0;
            }
            // Triple-chain reservoir early in the stream
            if post_residual >= 3 * next_item_size && progress < 0.6 {
                score -= 4.0;
            }
            // Tight chain fill discrimination
            if slack > 0.0 && slack < nxt * 0.15 {
                score -= 6.0 * (1.0 - slack / (nxt * 0.15));
            }
            // Small viable slack is a prime chain candidate
            if slack >= nxt && slack <= 25.0 {
                score -= (25.0 - slack) * 0.45;
            }
            // Complement harmony: pair hits capacity or half capacity
            if pr + nxt == cap {
                score -= 16.0;
            } else if pr + nxt == cap * 0.5 {
                score -= 9.0;
            }
            // Exact-fill cascade: item + next nearly consumes post residual
            if (post_residual - next_item_size) as u32 <= item_size.min(next_item_size) {
                score -= 4.0;
