    }

    // Endgame tightening
    if progress > 0.7 && post_residual > 0 {
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 5.0 * progress;
        } else {
            score += 6.0 * (residual_f / cap_f) * progress;
        }
    }

    // Mid-stream salvage threshold
    if next_item_size > 0 && post_residual >= next_item_size + 5 && fitting_bins_count > 2 && progress < 0.5 {
        score -= 3.5;
    }

    // Dead-space floor penalty scaled by remaining stream length
    if post_residual > 0 && post_residual < 8 && progress < 0.85 {
        score += (8 - post_residual) as f64 * (1.0 - progress) * 2.2;
    }

    // Reusable band around mean residual
    if post_residual > 0 {
        let band = ((residual_f - mean_residual).abs() / cap_f).min(1.0);
        score -= (1.0 - band) * 4.0 * (1.0 - progress);
    }

    // Inter-item gap coupling
    if next_item_size > 0 && fitting_bins_count <= 2 && post_residual >= next_item_size && bin_residual != bin_capacity {
        let margin = (post_residual - next_item_size) as f64;
        score -= margin.min(30.0) * 0.35 * (1.0 - progress);
    }

    // Best-fit discrimination among competing fitting bins
    if fitting_bins_count > 1 && post_residual > 0 && bin_residual != bin_capacity {
        let tight = 1.0 - (post_residual as f64 / cap_f);
        score -= tight * 8.0 / fitting_bins_count as f64;
    }

    // Residual divisibility
    if next_item_size > 1 && post_residual > 0 && post_residual % next_item_size == 0 && post_residual >= next_item_size {
        score -= 6.0;
    }

    // NEW MUTATION: exact-fill cascade strengthened — item+next nearly consumes post_residual,
    // weighted by progress to consolidate late-stream.
    if next_item_size > 0 && post_residual > next_item_size
        && (post_residual - next_item_size) <= item_size.min(next_item_size) {
        score -= 4.0 + 3.0 * progress;
    }

    // NEW MUTATION: waste-budget lookahead — if open bins' total residual already covers the
    // next item comfortably, discourage opening a new bin.
    if bin_residual == bin_capacity && next_item_size > 0 {
        let avg_fit = mean_residual / (next_item_size as f64).max(1.0);
        if avg_fit > 1.5 {
            score += 8.0 * (avg_fit - 1.5).min(2.0);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Core: quadratic penalty on post residual (dead space), scaled by capacity.
    let mut score = (post / cap) * (post / cap) * 40.0 + post * 0.35;

    // Smooth cubic coupling of dead space with stream progress:
    // later in the stream, wasting space is increasingly costly.
    let progress_coupling = post / cap * (0.5 + 2.5 * progress * progress);
    score += progress_coupling * 10.0;

    // Reward tight fits: interaction between item size fraction and residual.
    let fit_frac = item_size as f64 / bin_residual.max(1) as f64;
    score -= fit_frac * fit_frac * 12.0;

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count <= 1 {
        score -= 25.0 + 20.0 * progress;
    }

    // Lookahead: if the next item fits exactly in the post residual, reward this placement.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= post {
            let gap = post - nx;
            score -= 15.0 * (1.0 - gap / cap);
        } else {
            // next item won't fit here; slight penalty proportional to overshoot
            score += 5.0 * ((nx - post) / cap);
        }
    }

    // Mild dispersion penalty: bins far from the mean residual create fragmentation.
    let dev = (bin_residual as f64 - mean_residual).abs() / cap;
    score += dev * dev * 8.0;

    // Slight preference to fill existing bins rather than open new ones as stream matures.
    if bin_residual == bin_capacity {
        score += 18.0 + 12.0 * progress;
    } else {
        score -= 6.0;
    }

    // Smooth open-bin pressure: many open bins -> favor consolidating into existing ones.
    score += (open_bins_count as f64).ln().max(0.0) * 1.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let residual_f = post_residual as f64;
    let cap_f = bin_capacity as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
