    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        let dead_ratio = post_residual as f64 / next_item_size as f64;
        score += (1.0 - dead_ratio) * 8.0;
        if residual_f > mean_residual {
            score += (residual_f - mean_residual) * 0.22 * (0.5 + progress);
        }
    }

    if next_item_size > 0 && post_residual >= 3 * next_item_size && progress < 0.6 {
        score -= 4.0;
    }

    if post_residual > 0 && progress < 0.9 {
        let usable = (post_residual.min(100)) as f64 / 100.0;
        score -= usable * (1.0 - progress) * 6.0;
    }

    if progress > 0.7 && post_residual > 0 {
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 5.0 * progress;
        } else {
            score += 6.0 * (residual_f / cap_f) * progress;
        }
    }

    if next_item_size > 0 && post_residual > next_item_size
        && (post_residual - next_item_size) <= item_size.min(next_item_size) {
        score -= 4.0;
    }

    if next_item_size > 0 && post_residual >= next_item_size + 5 && fitting_bins_count > 2 && progress < 0.5 {
        score -= 3.5;
    }

    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        let stranded = (next_item_size - post_residual) as f64 / cap_f;
        score += stranded * 30.0 * (0.4 + 0.6 * progress);
    }

    if fitting_bins_count > 1 && post_residual > 0 {
        let tight = 1.0 - (post_residual as f64 / cap_f);
        score -= tight * 8.0 / fitting_bins_count as f64;
    }

    if next_item_size > 1 && post_residual > 0 && post_residual % next_item_size == 0 && post_residual >= next_item_size {
        score -= 6.0;
    }

    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        let fill = bin_residual as f64 / cap_f;
        if fill > 0.75 {
            score -= (fill - 0.75) * 20.0;
        } else if fill < 0.5 {
            score += (0.5 - fill) * 16.0;
        }
    }

    if next_item_size > 0 && fitting_bins_count <= 2 && post_residual >= next_item_size {
        let margin = (post_residual - next_item_size) as f64;
        score -= margin.min(30.0) * 0.35 * (1.0 - progress);
    }

    // MUTATION (refined dead-space ratio weakness): graded salvageability of the
    // dead residual against the *global* mean residual scale. A dead residual
    // that is small relative to mean_residual wastes less expected capacity —
    // penalize proportionally rather than flatly, and reward near-mean dead
    // residuals that could still absorb average-sized future items.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        let mean_scale = if mean_residual > 0.5 { mean_residual } else { cap_f * 0.1 };
        let salvage = (post_residual as f64 / mean_scale).min(1.0);
        score -= salvage * 7.0 * (1.0 - progress);
        // Extra: dead residual exactly equal to mean_residual is the least wasteful
        if (post_residual as f64 - mean_scale).abs() < 1.0 {
            score -= 3.0;
        }
    }

    // MUTATION: chain-depth bonus — post_residual supporting the next item AND
    // leaving a remainder that itself exceeds the next item implies a 3-chain;
    // reward proportional to depth, strongest mid-stream.
    if next_item_size > 1 && post_residual >= 2 * next_item_size {
        let depth = ((post_residual / next_item_size) as f64).min(4.0);
        score -= (depth - 1.0) * (3.5 - 2.0 * progress).max(1.0);
    }

    // MUTATION: waste-budget trigger — when aggregate open-bin residual drifts
    // far above the mean, tighten selection by amplifying the fill preference.
    if open_bins_count > 4 && mean_residual / cap_f > 0.25 {
        score += (mean_residual / cap_f - 0.25) * 18.0 * (0.5 + progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let residual_f = post_residual as f64;
    let cap_f = bin_capacity as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let is_new_bin = bin_residual == bin_capacity;
    let mut score = residual_f;

    // Tightness reward (quadratic)
    let tightness = 1.0 - (residual_f / cap_f).min(1.0);
    score -= 12.0 * tightness * tightness;

    if next_item_size > 0 {
        if post_residual == next_item_size && !is_new_bin {
            score -= 60.0;
        } else if post_residual > next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 10.0 + slack * 0.25 + (1.0 - (slack / cap_f).min(1.0)) * 8.0;
            if (slack as u32) >= next_item_size {
                score -= 9.0;
            }
            if slack >= next_item_size as f64 && slack <= 25.0 {
                score -= (25.0 - slack) * 0.5;
            }
        } else if post_residual > 0 {
            let gap = (next_item_size - post_residual) as f64;
            score += gap * 0.9;
            // dead-space budget scaled by progress
            score += (gap / cap_f) * 28.0 * (0.4 + 0.6 * progress);
            // fill-level trade: full bins tolerate dead residual, empty-ish bins don't
            let fill = bin_residual as f64 / cap_f;
            if fill > 0.75 {
                score -= (fill - 0.75) * 20.0;
            } else if fill < 0.5 {
                score += (0.5 - fill) * 16.0;
            }
        }
    }

    // Complement harmony
    if next_item_size > 0 && post_residual > next_item_size {
        let pair = residual_f + next_item_size as f64;
        if pair == cap_f {
            score -= 16.0;
        } else if pair == cap_f * 0.5 {
            score -= 8.0;
        }
    }

    // Density coupling: prefer tighter bins, progress-scaled
    score -= ((mean_residual - residual_f) / cap_f) * (28.0 + 12.0 * progress);

    // Last-chance bin
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 30.0;
    } else if fitting_bins_count > 1 && fitting_bins_count <= 3 && !is_new_bin {
        score -= (4.0 - fitting_bins_count as f64) * 5.0;
    }

    // Perfect completion
    if post_residual == 0 && !is_new_bin {
        score -= 17.0;
    }

    // Near-perfect fill bonus
    if post_residual > 0 && post_residual <= 6 && !is_new_bin {
        score -= 10.0 + (6 - post_residual) as f64 * 1.5;
    }

    // Best-fit discrimination among fitting bins
    if fitting_bins_count > 1 && post_residual > 0 {
        score -= tightness * 8.0 / fitting_bins_count as f64;
    }

    // New-bin candidate logic
    if is_new_bin {
        if next_item_size > 0 && (item_size + next_item_size) == bin_capacity {
            score -= 40.0;
        } else if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score -= 8.0;
        } else {
            let waste_factor = ((mean_residual / cap_f) - 0.1).max(0.0);
            let none_fit_next = next_item_size > 0 && post_residual < next_item_size;
            score += 24.0 + 0.2 * open_bins_count as f64 + waste_factor * 22.0
                + if none_fit_next { -8.0 } else { 0.0 };
        }
        score += progress * 20.0;
        if progress > 0.85 {
            score += 12.0 * (progress - 0.85) * 20.0;
        }
        // Restraint when a >=90% fill is available elsewhere
        if next_item_size > 0 && post_residual > 0 && post_residual <= bin_capacity / 10 {
            score += 14.0;
        }
    } else {
        score -= 0.05 * open_bins_count as f64;
    }

    // Late-stream consolidation
    score += progress * progress * 14.0 * (residual_f / cap_f);

    // Salvageability early in stream
    if post_residual > 0 && progress < 0.9 {
        let usable = (post_residual.min(100)) as f64 / 100.0;
        score -= usable * (1.0 - progress) * 6.0;
    }

    // Endgame chain-fill preference
    if progress > 0.7 && post_residual > 0 {
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 5.0 * progress;
        } else {
            score += 6.0 * (residual_f / cap_f) * progress;
        }
    }

    // Fragmentation guard
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size / 2 && !is_new_bin {
        score += 8.0;
    }

    // Divisibility promise
    if next_item_size > 1 && post_residual > 0 && post_residual % next_item_size == 0 && post_residual >= next_item_size {
        score -= 6.0;
    }

    // Inter-item gap coupling when few bins fit
    if next_item_size > 0 && fitting_bins_count <= 2 && post_residual >= next_item_size && !is_new_bin {
        let margin = (post_residual - next_item_size) as f64;
        score -= margin.min(30.0) * 0.35 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls into "usable"
    // classes (multiples of small denominators of capacity) are preferred.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Dead-space penalty: leftover too small to fit typical items (<=10)
    if post_residual < 10 && post_residual > 0 {
        score += 25.0;
    }

    // Perfect fit reward
    if post_residual == 0 {
        score -= 60.0;
    }

    // Harmonic classes: post_residual in {0, 20, 25, 33, 50, 100} style fractions
    let hclass = (post_residual * 4) % bin_capacity; // modulo arithmetic on capacity quarters
    if hclass == 0 && post_residual > 0 && post_residual < bin_capacity {
        score -= 8.0; // aligns with quarter-capacity classes
    }
    let hclass2 = (post_residual * 5) % bin_capacity;
    if hclass2 == 0 && post_residual > 0 && post_residual < bin_capacity {
        score -= 6.0; // fifth-harmonic alignment
    }

    // Lookahead: reward if next item fits exactly in post_residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0;
        } else if next_item_size <= post_residual {
            score -= (post_residual - next_item_size) as f64 * 0.3;
        } else {
            score += 5.0; // next item won't fit here; leftover likely wasted
        }
        // Integer division threshold: next item "large class" (>50)
        if next_item_size > 50 && post_residual >= next_item_size {
            score -= 10.0; // secure space for big next item
        }
    }

    // Last-chance bin bonus: only fitting bin before opening a new one
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Prefer tight bins relative to mean residual (best-fit coupling)
    if (post as f64) < mean_residual {
        score -= 4.0;
    } else {
        score += 2.0;
    }

    // Penalize opening new bins when many open bins could fit
    if bin_residual == bin_capacity {
        // new-bin candidate: baseline score = full capacity
        score = cap;
        if fitting_bins_count > 0 {
            score += 30.0; // discourage new bin if any open bin fits
        }
        if next_item_size > 0 && next_item_size >= 70 {
            score -= 10.0; // big next item: fresh bin attractive
        }
    }

    // Mild stream-progression pressure: later in stream, consolidate more
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 3.0 * (open_bins_count as f64).sqrt().min(5.0);

    score
}

