    // Last-chance bin: strongly favor using the only fitting bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    } else if fitting_bins_count > 0 && fitting_bins_count <= 3 && bin_residual != bin_capacity {
        score -= (4.0 - fitting_bins_count as f64) * 5.5;
    }

    // New-bin candidate logic
    if bin_residual == bin_capacity {
        if next_item_size > 0 && (item_size + next_item_size) == bin_capacity {
            score -= 46.0;
        } else if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score -= 10.0;
        } else {
            let waste_factor = ((mean_residual / cap_f) - 0.1).max(0.0);
            let none_fit_next = next_item_size > 0 && post_residual < next_item_size;
            let open_bonus = if none_fit_next { -8.0 } else { 0.0 };
            score += 26.0 + 0.2 * open_bins_count as f64 + waste_factor * 22.0 + open_bonus;
        }
        score += progress * 20.0;
        if next_item_size > 0 && post_residual > 0 && post_residual <= bin_capacity / 10 {
            score += 14.0;
        }
        if progress > 0.85 {
            score += 12.0 * (progress - 0.85) * 20.0;
        }
    }

    // Late-stream consolidation: penalize leaving large residuals as stream progresses
    score += progress * progress * 14.0 * (residual_f / cap_f);

    // Small tie-break: prefer filling bins with higher current fill
    score -= (bin_residual as f64 / cap_f) * 5.0;

    // Dead-space guard: penalize residuals too small for typical upcoming items
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 0.40;
    }

    // Fragmentation guard: residuals below half of next item are nearly dead
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size / 2 {
        score += 10.0;
    }

    // Perfect-completion bonus: bin becomes exactly full after this item
    if post_residual == 0 && bin_residual != bin_capacity {
        score -= 17.0;
        if next_item_size > 0 && bin_residual % next_item_size == 0 {
            score -= 5.0;
        }
    }

    // Near-perfect fill bonus: residuals up to 6 are almost full
    if post_residual > 0 && post_residual <= 6 && bin_residual != bin_capacity {
        if post_residual <= 3 {
            score -= 10.0 + (4 - post_residual) as f64 * 3.0;
        } else {
            score -= 12.0 - (post_residual - 3) as f64 * 2.0;
        }
    }

    // Residual-vs-mean dead-space ratio: wasteful bins penalized softly
    if residual_f > mean_residual {
        score += (residual_f - mean_residual) * 0.14;
    }

    // Harmony bonus — item exactly halves the residual (classic pairing)
    if bin_residual > item_size && (bin_residual - item_size) == item_size {
        score -= 9.0;
    }

    // Escalated dead-space penalty for very small unusable residuals
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size.min(20) {
        score += 5.0;
    }

    // Combined fine-grained fit + lookahead coupling
    if next_item_size > 0 && post_residual >= next_item_size {
        let remainder = post_residual - next_item_size;
        if remainder > 0 && remainder < next_item_size {
            score += 2.0;
        }
        score -= ((next_item_size * 4) as f64 / (residual_f + 1.0)) * 3.0;
    }

    // Dead-space ratio guard using mean residual as reference scale
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        let dead_ratio = post_residual as f64 / next_item_size as f64;
        score += (1.0 - dead_ratio) * 8.0;
        if residual_f > mean_residual {
            score += (residual_f - mean_residual) * 0.22 * (0.5 + progress);
        }
    }

    // Triple-chain lookahead — versatile reservoir early in the stream
    if next_item_size > 0 && post_residual >= 3 * next_item_size && progress < 0.6 {
        score -= 4.0;
    }

    // Salvageability coupling — residual reusable by a wide range of items
    if post_residual > 0 && progress < 0.9 {
        let usable = (post_residual.min(100)) as f64 / 100.0;
        score -= usable * (1.0 - progress) * 6.0;
    }

    // Endgame tightening — prefer chain-fillable bins near stream end
    if progress > 0.7 && post_residual > 0 {
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 5.0 * progress;
        } else {
            score += 6.0 * (residual_f / cap_f) * progress;
        }
    }

    // Exact-fill cascade — item + next item nearly consumes post_residual
    if next_item_size > 0 && post_residual > next_item_size
        && (post_residual - next_item_size) <= item_size.min(next_item_size) {
        score -= 4.0;
    }

    // Mid-stream salvage threshold — keep versatile bins open when several compete
    if next_item_size > 0 && post_residual >= next_item_size + 5 && fitting_bins_count > 2 && progress < 0.5 {
        score -= 3.5;
    }

    // Dead-space budget coupling — stranded potential scaled by progress
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        let stranded = (next_item_size - post_residual) as f64 / cap_f;
        score += stranded * 30.0 * (0.4 + 0.6 * progress);
    }

    // Best-fit discrimination among fitting bins — tightest placement rewarded
    if fitting_bins_count > 1 && post_residual > 0 {
        let tight = 1.0 - (post_residual as f64 / cap_f);
        score -= tight * 8.0 / fitting_bins_count as f64;
    }

    // Residual divisibility — clean multiple of the next item promises exact fills
    if next_item_size > 1 && post_residual > 0 && post_residual % next_item_size == 0 && post_residual >= next_item_size {
        score -= 6.0;
    }

    // Fill-level vs. dead-space trade — a very full bin can tolerate a small
    // dead residual (bounded cost), a half-empty bin with dead residual is
    // doubly bad. Refined: scale with progress so late-stream fills weigh more.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        let fill = bin_residual as f64 / cap_f;
        if fill > 0.75 {
            score -= (fill - 0.75) * 20.0 * (1.0 + progress);
        } else if fill < 0.5 {
            score += (0.5 - fill) * 16.0 * (1.0 + 0.5 * progress);
        }
    }

    // Inter-item gap coupling — when few bins fit, preserve the bin that can
    // host the next item most flexibly.
    if next_item_size > 0 && fitting_bins_count <= 2 && post_residual >= next_item_size {
        let margin = (post_residual - next_item_size) as f64;
        score -= margin.min(30.0) * 0.35 * (1.0 - progress);
    }

    // NEW MUTATION: dead-space percentile guard — residuals that are both
    // below the mean residual AND unusable by the next item are the primary
    // source of fragmentation; penalize quadratically in the gap.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        let gap = (next_item_size - post_residual) as f64;
        if residual_f < mean_residual {
            score += (gap * gap) / (cap_f * 2.0);
        }
    }

    // NEW MUTATION: dual-fit lookahead — reward residuals that can absorb the
    // next item AND leave a remainder still >= a plausible future item
    // (approximated by item_size, the current stream sample).
    if next_item_size > 0 && post_residual >= next_item_size {
        let remainder = post_residual - next_item_size;
        if remainder >= item_size && remainder >= next_item_size {
            score -= 5.0 * (1.0 - progress);
        } else if remainder > 0 && remainder < item_size.min(next_item_size) {
            // remainder too small for either reference size: soft penalty
            score += 1.5 * progress;
        }
    }

    // NEW MUTATION: mean-residual alignment bonus — placing into a bin whose
    // post residual lands near the current mean residual keeps future
    // fitting options uniform across open bins, easing later compaction.
    if post_residual > 0 {
        let align = 1.0 - ((residual_f - mean_residual).abs() / cap_f).min(1.0);
        score -= align * 3.0 * (1.0 - progress);
    }

    // NEW MUTATION: new-bin discipline refinement — opening a bin when the
    // current item would leave a residual smaller than the next item in an
    // existing bin is wasteful; conversely, opening is worse when many bins
    // are already open and mean residual is healthy.
    if bin_residual == bin_capacity && next_item_size > 0 {
        let healthy_mean = mean_residual / cap_f;
        if healthy_mean > 0.25 && open_bins_count > 2 {
            score += (healthy_mean - 0.25) * 30.0 + (open_bins_count.min(12) as f64) * 0.8;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals below the minimum plausible
    // item size are essentially unusable; penalize them heavily.
    if post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 25.0;
    } else if post_residual < 30 {
        score += 10.0;
    }

    // Reward tight fits (small post_residual relative to bin capacity).
    let tightness = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
    score -= 20.0 * tightness;

    // Perfect fit: huge reward.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 35.0;
    }

    // Open-bin pressure: discourage spreading across many open bins,
    // encouraging consolidation into fewer bins.
    score += 0.8 * open_bins_count as f64;

    // Prefer bins whose residual is below the mean (fill fuller bins first),
    // which concentrates items and leaves larger residuals elsewhere.
    score += (bin_residual as f64 - mean_residual) * 0.3;

    // Lookahead: if the next item fits exactly in the post-residual,
    // reward creating that opportunity; if post-residual can't fit any
    // plausible next item, discourage wasting this bin.
    if next_item_size > 0 {
        if post_residual >= next_item_size && post_residual - next_item_size < 10 {
            score -= 15.0;
        }
        if post_residual < next_item_size && post_residual > 0 && post_residual < 10 {
            score += 20.0;
        }
    }

    // New empty bin candidate: make it unattractive unless the current
    // item is large relative to the residual (poor fits elsewhere) or
    // no open bin is a good option. Penalize mildly so existing bins win
    // on tight fits, but allow it when dead space would be created.
    if bin_residual == bin_capacity {
        score += 45.0;
        if item_size > bin_capacity * 3 / 4 {
            score -= 40.0;
        }
        if fitting_bins_count == 0 {
            score -= 60.0;
        }
    }

    // Slight progression bias: as the stream advances, be more willing
    // to open bins early rather than fragmenting late.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

