pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: strongly reward bins whose post-residual
    // can exactly or nearly fit the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            // Perfect 2-chain match gets a big discount.
            if slack == 0.0 {
                score -= 40.0;
            } else {
                // Discount proportional to how tight the chain is.
                score -= 25.0 * (1.0 - slack / bin_capacity as f64);
            }
        } else {
            // Next item cannot follow here: penalize proportionally to the gap.
            let gap = (next_item_size - post_residual) as f64;
            score += 8.0 * (gap / bin_capacity as f64);
        }
    }

    // Compare against mean residual: placing into a bin whose residual is
    // far above mean tends to leave scattered large holes elsewhere.
    score += 0.35 * ((bin_residual as f64 - mean_residual).abs());

    // Last-chance bin: if this is the only bin that fits, avoid opening a new
    // bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 18.0;
    }

    // Penalize creating tiny dead space that nothing (min size 1..) can use.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Slight preference for filling bins tightly as the stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 5.0 * progress * (item_size as f64 / bin_capacity as f64);

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        score += 12.0;
        if fitting_bins_count == 0 {
            score -= 60.0;
        }
    }

    score
}

