    // Best-fit discrimination among fitting bins — tightest placement rewarded
    if fitting_bins_count > 1 && post_residual > 0 {
        let tight = 1.0 - (post_residual as f64 / cap_f);
        score -= tight * 8.0 / fitting_bins_count as f64;
    }

    // Residual divisibility — clean multiple of the next item promises exact fills
    if next_item_size > 1 && post_residual > 0 && post_residual % next_item_size == 0 && post_residual >= next_item_size {
        score -= 6.0;
    }

    // Fill-level vs. dead-space trade
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        let fill = bin_residual as f64 / cap_f;
        if fill > 0.75 {
            score -= (fill - 0.75) * 20.0;
        } else if fill < 0.5 {
            score += (0.5 - fill) * 16.0;
        }
    }

    // Inter-item gap coupling — preserve the bin that hosts the next item flexibly
    if next_item_size > 0 && fitting_bins_count <= 2 && post_residual >= next_item_size {
        let margin = (post_residual - next_item_size) as f64;
        score -= margin.min(30.0) * 0.35 * (1.0 - progress);
    }

    // NEW MUTATION: dead-space vs. open-bin pressure — when many bins are open,
    // a dead residual is more forgivable (bin will likely be consumed later);
    // when few bins are open, dead space is a real loss. Also scale by how far
    // the dead residual sits below the mean residual: a bin whose residual is
    // much smaller than average wastes proportionally less of the stream's
    // remaining flexibility.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        let openness = (open_bins_count as f64).min(20.0) / 20.0;
        let below_mean = ((mean_residual - residual_f) / cap_f).max(0.0);
        score -= openness * 9.0 + below_mean * 14.0;
        // Late-stream: dead residuals in nearly-full bins become permanent loss —
        // only spare them when they are tiny relative to capacity.
        if progress > 0.75 && (post_residual as f64) > cap_f * 0.05 {
            score += 6.0 * (1.0 - openness);
        }
    }

    // NEW MUTATION: two-item lookahead packing — if the residual after placing
    // this item could hold next_item plus a typical fraction of itself, this
    // bin is a strong chain anchor; reward proportionally to tightness.
    if next_item_size > 0 && post_residual >= next_item_size && post_residual < next_item_size * 2 {
        let chain_fill = post_residual as f64 / (2.0 * next_item_size as f64);
        score -= (1.0 - chain_fill) * 7.0 * (1.0 - progress * 0.5);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits (small dead space).
    score -= 1.5 * (bin_capacity as f64 - post_residual as f64) / bin_capacity as f64 * (item_size as f64 / bin_capacity as f64);

    // Penalize leaving awkward residuals that few items can use.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    } else if post_residual < 20 {
        score += 8.0;
    }

    // Exact fit is perfect.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Last-chance bonus: if this is the only fitting bin, prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Lookahead: reward bins whose post-residual can still host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size as u32 {
            score -= 6.0 + 4.0 * (next_item_size as f64 / bin_capacity as f64);
        } else {
            score += 5.0;
        }
    }

    // New-bin candidate handling: opening a new bin is attractive when current
    // bins have poor fit or the item is large relative to residuals.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let waste_pressure = (mean_residual - item_size as f64).max(0.0);
        // Base cost of a fresh bin, discounted when open bins are fragmented.
        score = bin_capacity as f64 * 0.9
            - waste_pressure * 0.6
            - (open_bins_count as f64) * 0.3
            - progress * 5.0;
        // If the item fits poorly everywhere, opening new bin is good.
        if post_residual == 0 {
            score -= 10.0;
        }
    }

    // Time-horizon modulation: late in the stream, consolidate aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (bin_residual as f64 - post_residual as f64) * 0.2;

    // Mild penalty for spreading across many open bins.
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
