    if post_residual == 0 && !is_new_bin {
        score -= 17.0;
        if next_item_size > 0 && bin_residual % next_item_size == 0 {
            score -= 5.0;
        }
    }

    // Near-perfect fill bonus
    if post_residual > 0 && post_residual <= 6 && !is_new_bin {
        if post_residual <= 3 {
            score -= 10.0 + (4 - post_residual) as f64 * 3.0;
        } else {
            score -= 12.0 - (post_residual - 3) as f64 * 2.0;
        }
    }

    // Salvageability — residual reusable by wide range of items
    if post_residual > 0 && !is_new_bin && progress < 0.9 {
        let usable = (post_residual.min(100)) as f64 / 100.0;
        score -= usable * (1.0 - progress) * 6.0;
    }

    // Endgame tightening
    if progress > 0.7 && post_residual > 0 && !is_new_bin {
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 5.0 * progress;
        } else {
            score += 6.0 * (residual_f / cap_f) * progress;
        }
    }

    // Best-fit discrimination among competing bins
    if fitting_bins_count > 1 && post_residual > 0 && !is_new_bin {
        score -= tightness * 8.0 / fitting_bins_count as f64;
    }

    // Inter-item gap coupling when few bins fit
    if next_item_size > 0 && fitting_bins_count <= 2 && post_residual >= next_item_size && !is_new_bin {
        let margin = (post_residual - next_item_size) as f64;
