    let norm_item = item_size as f64 / cap;
    let norm_next = next_item_size as f64 / cap;

    // Base: prefer tight fits (small post_residual), with quadratic sharpening.
    let mut score = pr * (1.0 + 1.5 * norm_pr * norm_pr);

    // Smooth progress coupling: later in stream, penalize large residuals more.
    score += 20.0 * progress * norm_pr * norm_pr;

    // Reward if next item fits in post_residual (smooth cosine-like gate).
    let fits_next = if next_item_size > 0 && post_residual >= next_item_size { 1.0 } else { 0.0 };
    let tightness = 1.0 - norm_pr;
    score -= 8.0 * fits_next * (1.0 - (norm_next - norm_pr).abs()) * (0.5 + 0.5 * progress);

    // Penalize dead space too small for typical items (smooth non-linear).
    let dead = (1.0 - norm_pr).min(1.0);
    score += 6.0 * dead * dead * (1.0 - fits_next);

    // Last-chance bonus: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 + progress);
