pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;

    // Harmonic class of post_residual: bins whose leftover falls into "nice"
    // classes (multiples of 10, or exactly matching common item sizes) are
    // more likely to be filled later -> reward them.
    let pr = post_residual;
    let class_bonus = if pr == 0 {
        -60.0 // perfect fit, best outcome
    } else if pr % 10 == 0 {
        -18.0
    } else if pr <= 5 {
        -12.0 // tiny dead space, nearly perfect
    } else if pr % 10 <= 2 || pr % 10 >= 8 {
        -6.0
    } else {
        8.0 // awkward leftover class
    };
    score += class_bonus;

    // Lookahead: does the next item fit exactly / well in the post residual?
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 45.0; // chains a perfect fit
        } else if next_item_size <= pr {
            let ratio = next_item_size as f64 / pr as f64;
            score -= 20.0 * ratio; // next item consumes most of leftover
        } else {
            // next item cannot fit here; penalize more if leftover is large
            score += 0.15 * (pr as f64 - next_item_size as f64).abs();
        }
    } else {
        // last item: prefer minimizing leftover outright
        score += 0.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening a new bin, scaled by how many
    // open bins exist and how good the fit would be elsewhere.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let waste = cap - item_size as f64;
        score += 55.0 + 0.6 * waste + 25.0 * progress;
        // early on, opening bins is cheaper; late, prefer consolidation
        score -= 40.0 * (1.0 - progress);
    }

    // Prefer bins with residual below mean (tighter bins first) to keep
    // large residuals available for large future items.
    score += 0.10 * (mean_residual - bin_residual as f64);

    // Mild preference for using more-open bins (consolidation pressure).
    score -= 0.5 * open_bins_count as f64;

    score
}

