        let margin = (post_residual - next_item_size) as f64;
        score -= margin.min(30.0) * 0.35 * (1.0 - progress);
    }

    // NEW MUTATION A: dead-space ratio refinement — grade the deadness of a
    // residual continuously rather than with hard thresholds. A residual just
    // below next_item_size is far more salvageable than one far below.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        let near_miss = 1.0 - (post_residual as f64 / next_item_size as f64);
        // near_miss in (0,1): 0 = almost fits, 1 = tiny dead space
        score += near_miss * near_miss * 9.0 * (0.5 + progress);
        // but if the residual could still absorb a *typical* small item
        // (mean residual scale), soften the penalty
        if post_residual as f64 >= mean_residual * 0.6 {
            score -= 3.0;
        }
    }

    // NEW MUTATION B: two-step compaction lookahead — prefer placements whose
    // post_residual equals item_size + next_item_size or leaves a residual
    // exactly equal to a plausible future complement (cap - next_item_size).
    if next_item_size > 0 && post_residual > 0 {
        if post_residual == item_size + next_item_size && post_residual <= bin_capacity {
            score -= 8.0 * (1.0 - progress);
        }
        let complement = bin_capacity.saturating_sub(next_item_size);
        if complement > 0 && post_residual == complement {
            score -= 7.0;
        }
    }

    // NEW MUTATION C: waste-velocity term — when many bins are open relative to
    // progress, mildly discourage creating yet another partially-filled bin;
    // when bins are scarce, encourage consolidating into the fullest bin.
    let open_pressure = open_bins_count as f64 / (1.0 + 40.0 * (1.0 - progress));
    if bin_residual != bin_capacity {
        score += (open_pressure - 1.0).max(0.0) * 2.5 * (residual_f / cap_f);
    }

    // NEW MUTATION D: endgame exact-fit sharpening — in the final stretch,
    // an exact zero post_residual is worth much more; a residual that cannot
    // ever fit the next item is worth much less.
    if progress > 0.8 {
        if post_residual == 0 {
            score -= 8.0 * progress;
        } else if next_item_size > 0 && post_residual < next_item_size {
            score += 4.0 * progress;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect two-step fit: item now + next item exactly fills the bin.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // Next item fits into the remaining space (good 2-step lookahead).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0 + 0.25 * next_item_size as f64;
    } else if next_item_size > 0 {
        // Dead space the next item cannot use.
        score += 0.4 * (post_residual as f64 - next_item_size as f64).abs();
    }

    // Reward tight fits relative to current item size.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 10.0 * fill_ratio;

    // Penalize residuals far from the mean residual (fragmentation risk).
    score += 0.3 * (post_residual as f64 - mean_residual).abs();

    // Last-chance bin: strongly prefer using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Slight preference for reusing already-open bins over opening new ones.
    if bin_residual == bin_capacity {
        score += 20.0 + 0.1 * open_bins_count as f64;
    }

    // Late in the stream, compact more aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 8.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
