    // plus a tiny scrap (<=2), leaving near-zero waste; reward strongly.
    if next_item_size > 0 && post_residual > next_item_size && (post_residual - next_item_size) <= 2 {
        score -= 8.0 + (2 - (post_residual - next_item_size)) as f64 * 4.0;
    }

    score
}

