        let large_item = item_size as f64 / bin_capacity as f64;
        score -= 25.0 * large_item;
        // Late in the stream, prefer packing into existing bins.
        score += 30.0 * progress;
        // If other bins fit, opening new bins is wasteful unless item is huge.
        if fitting_bins_count > 0 && item_size < 60 {
