            if slack > 0.0 && slack < (next_item_size as f64) * 0.15 && bin_residual as f64 >= cap_f * 0.5 {
                score -= 6.0 * (1.0 - slack / ((next_item_size as f64) * 0.15));
            }
            if post_residual >= 2 * next_item_size && post_residual as f64 <= cap_f * 0.5 {
                score -= 7.0;
            }
            if slack > 0.0 && (slack as u32) % next_item_size.max(1) == 0 && slack <= 3.0 * next_item_size as f64 {
                score -= 5.0;
            }
            if (post_residual - next_item_size) <= item_size.min(next_item_size) {
                score -= 4.0;
            }
        } else if post_residual > 0 {
            let gap = (next_item_size - post_residual) as f64;
            score += gap * 0.95;
        }
    }

    // Complement harmony — post_residual pairs with next item to a round target
    if next_item_size > 0 && post_residual > next_item_size {
        let pair = residual_f + next_item_size as f64;
        if pair == cap_f {
            score -= 18.0;
        } else if pair == cap_f * 0.5 {
            score -= 10.0;
        }
    }

    // Density coupling: prefer bins tighter than mean residual (progress-scaled)
    let density_gap = (mean_residual - residual_f) / cap_f;
    score -= density_gap * (30.0 + 12.0 * progress);

    // Last-chance bin: strongly favor using the only fitting bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    } else if fitting_bins_count > 0 && fitting_bins_count <= 3 && bin_residual != bin_capacity {
        score -= (4.0 - fitting_bins_count as f64) * 5.5;
    }

    // New-bin candidate logic
    if bin_residual == bin_capacity {
        if next_item_size > 0 && (item_size + next_item_size) == bin_capacity {
            score -= 46.0;
        } else if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score -= 10.0;
        } else {
            let waste_factor = ((mean_residual / cap_f) - 0.1).max(0.0);
            let none_fit_next = next_item_size > 0 && post_residual < next_item_size;
            let open_bonus = if none_fit_next { -8.0 } else { 0.0 };
            let tight_open_bins = next_item_size > 0 && item_size as f64 > mean_residual * 2.0;
            let tight_bonus = if tight_open_bins { -6.0 } else { 0.0 };
            score += 26.0 + 0.2 * open_bins_count as f64 + waste_factor * 22.0 + open_bonus + tight_bonus;
        }
        score += progress * 20.0;
        if next_item_size > 0 && post_residual > 0 && post_residual <= bin_capacity / 10 {
            score += 14.0;
        }
        if progress > 0.85 {
            score += 12.0 * (progress - 0.85) * 20.0;
        }
        // New-bin restraint when a decent (>=60% of next item) fit exists
        if next_item_size > 0 && fitting_bins_count > 0
            && post_residual >= (next_item_size as f64 * 0.6) as u32 && post_residual < next_item_size {
            score += 6.0 * (1.0 - progress);
        }
    }

    // Late-stream consolidation
    score += progress * progress * 14.0 * (residual_f / cap_f);

    // Small tie-break: prefer filling bins with higher current fill
    score -= (bin_residual as f64 / cap_f) * 5.0;

    // Dead-space guard
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 0.40;
    }

    // Fragmentation guard
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size / 2 {
        score += 10.0;
    }

    // Perfect-completion bonus
    if post_residual == 0 && bin_residual != bin_capacity {
        score -= 17.0;
        if next_item_size > 0 && bin_residual % next_item_size == 0 {
            score -= 5.0;
        }
    }

    // Near-perfect fill bonus
    if post_residual > 0 && post_residual <= 6 && bin_residual != bin_capacity {
        if post_residual <= 3 {
            score -= 10.0 + (4 - post_residual) as f64 * 3.0;
        } else {
            score -= 12.0 - (post_residual - 3) as f64 * 2.0;
        }
    }

    // Residual-vs-mean dead-space ratio
    if residual_f > mean_residual {
        score += (residual_f - mean_residual) * 0.14;
    }

    // Harmony bonus — item exactly halves the residual
    if bin_residual > item_size && (bin_residual - item_size) == item_size {
        score -= 9.0;
    }

    // Escalated dead-space penalty
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size.min(20) {
        score += 5.0;
    }

    // Combined fine-grained fit + lookahead coupling
    if next_item_size > 0 && post_residual >= next_item_size {
        let remainder = post_residual - next_item_size;
        if remainder > 0 && remainder < next_item_size {
            score += 2.0;
        }
        score -= ((next_item_size * 4) as f64 / (residual_f + 1.0)) * 3.0;
        if remainder >= 1 && remainder <= 10 && progress > 0.4 {
            score -= (11 - remainder) as f64 * 0.8 * progress;
        }
        if remainder >= next_item_size / 2 && remainder < next_item_size && progress < 0.7 {
            score -= 3.0;
        }
    }

    // Dead-space ratio guard using mean residual as reference scale
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        let dead_ratio = post_residual as f64 / next_item_size as f64;
        score += (1.0 - dead_ratio) * 8.0;
        if residual_f > mean_residual {
            score += (residual_f - mean_residual) * 0.22 * (0.5 + progress);
        }
        let stranded = (next_item_size - post_residual) as f64 / cap_f;
        score += stranded * 30.0 * (0.4 + 0.6 * progress);
        let fill = bin_residual as f64 / cap_f;
        if fill > 0.75 {
            score -= (fill - 0.75) * 20.0;
        } else if fill < 0.5 {
            score += (0.5 - fill) * 16.0;
        }
    }

    // Triple-chain lookahead
    if next_item_size > 0 && post_residual >= 3 * next_item_size && progress < 0.6 {
        score -= 4.0;
    }

    // Salvageability coupling
    if post_residual > 0 && progress < 0.9 {
        let usable = (post_residual.min(100)) as f64 / 100.0;
        score -= usable * (1.0 - progress) * 6.0;
    }

    // Endgame tightening
    if progress > 0.7 && post_residual > 0 {
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 5.0 * progress;
        } else {
            score += 6.0 * (residual_f / cap_f) * progress;
        }
    }

    // Mid-stream salvage threshold
    if next_item_size > 0 && post_residual >= next_item_size + 5 && fitting_bins_count > 2 && progress < 0.5 {
        score -= 3.5;
    }

    // Dead-space floor penalty scaled by remaining stream length
    if post_residual > 0 && post_residual < 8 && progress < 0.85 {
        score += (8 - post_residual) as f64 * (1.0 - progress) * 2.2;
    }

    // Reusable band around mean residual
    if post_residual > 0 {
        let band = ((residual_f - mean_residual).abs() / cap_f).min(1.0);
        score -= (1.0 - band) * 4.0 * (1.0 - progress);
    }

    // Inter-item gap coupling: preserve the most flexible host when few bins compete
    if next_item_size > 0 && fitting_bins_count <= 2 && post_residual >= next_item_size && bin_residual != bin_capacity {
        let margin = (post_residual - next_item_size) as f64;
        score -= margin.min(30.0) * 0.35 * (1.0 - progress);
    }

    // Best-fit discrimination among competing fitting bins
    if fitting_bins_count > 1 && post_residual > 0 && bin_residual != bin_capacity {
        let tight = 1.0 - (post_residual as f64 / cap_f);
        score -= tight * 8.0 / fitting_bins_count as f64;
    }

    // Residual divisibility — clean multiple of next item promises exact fills
    if next_item_size > 1 && post_residual > 0 && post_residual % next_item_size == 0 && post_residual >= next_item_size {
        score -= 6.0;
    }

    // MUTATION A: dead-space recovery — a "dead" residual may still be salvageable
    // if it exceeds a floor derived from mean residual; soften penalty early.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        let salvage_floor = (mean_residual * 0.5).min(next_item_size as f64 * 0.9);
        if post_residual as f64 >= salvage_floor {
            score -= 6.0 * (1.0 - progress);
        }
    }

    // MUTATION B: exact-post-fill fill-level coupling — reward bins that will be
    // left with exactly the next item, scaled by how full they already are.
    if next_item_size > 0 && post_residual == next_item_size && bin_residual != bin_capacity {
        let fill = bin_residual as f64 / cap_f;
        score -= 12.0 * fill;
    }

    // MUTATION C: residual bucket harmonics — gray-zone residuals (7..next) get
    // overshoot-scaled penalty, capped to avoid double counting.
    if next_item_size > 0 && post_residual >= 7 && post_residual < next_item_size {
        let overshoot = (next_item_size - post_residual) as f64;
        score += overshoot.min(20.0) * 0.25 * (0.5 + progress);
    }

    // MUTATION D: two-item packing lookahead — if item + next item exactly fills
    // the bin's current residual, this is a perfect pairing; reward strongly.
    if next_item_size > 0 && (item_size + next_item_size) == bin_residual && bin_residual != bin_capacity {
        score -= 15.0 * (1.0 - progress);
    }

    // MUTATION E: compaction coupling — when many bins are open, prefer the
    // placement that minimizes absolute leftover after both item and next item,
    // pushing toward closing bins rather than spreading.
    if next_item_size > 0 && post_residual >= next_item_size && open_bins_count > 4 {
        let two_step_waste = post_residual - next_item_size;
        if two_step_waste < item_size {
            score -= 4.0 * (1.0 - progress);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let nxt = next_item_size as f64;

    // Base: quadratic penalty on post residual, progress-modulated
    let mut score = norm_pr * (1.0 + 0.8 * norm_pr) * (1.0 + 0.5 * progress);

    // Exact chain fill: post residual perfectly absorbs next item
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0;
            // Exact-post-fill coupling: full bins chain best
            let fill = bin_residual as f64 / cap;
            score -= 12.0 * fill;
        } else if post_residual > next_item_size {
            let fit_ratio = (pr / nxt).min(3.0);
            let smooth = fit_ratio / (1.0 + fit_ratio);
            score -= 2.0 * smooth * (1.0 - progress * 0.5);
            let slack = (post_residual - next_item_size) as f64;
            // Two-chain lookahead: residual can absorb next item twice
            if post_residual >= 2 * next_item_size && pr <= cap * 0.5 {
                score -= 7.0;
            }
            // Triple-chain lookahead early in stream
            if post_residual >= 3 * next_item_size && progress < 0.6 {
                score -= 4.0;
            }
            // Tight chain fill discrimination
            if slack > 0.0 && slack < nxt * 0.15 {
                score -= 6.0 * (1.0 - slack / (nxt * 0.15));
            }
            // Slack that is itself a viable small residual is a prime chain candidate
            if slack >= nxt && slack <= 25.0 {
                score -= (25.0 - slack) * 0.55;
            }
            // Complement harmony: pair hits capacity or half capacity
            if pr + nxt == cap {
                score -= 18.0;
            } else if pr + nxt == cap * 0.5 {
                score -= 10.0;
            }
            // Exact-fill cascade: item + next item nearly consumes post_residual
            if slack <= item_size.min(next_item_size) as f64 {
                score -= 4.0;
            }
            // Residual divisibility — clean multiple of next item promises exact fills
            if next_item_size > 1 && post_residual % next_item_size == 0 {
                score -= 6.0;
            }
        } else {
            // Dead space: next item cannot fit into post residual
            let gap = nxt - pr;
            score += gap * 0.75;
            if post_residual > 0 && post_residual < next_item_size / 2 {
                score += 10.0;
            }
            // Dead-space ratio guard scaled by progress
            let dead_ratio = pr / nxt;
            score += (1.0 - dead_ratio) * 8.0 * (0.5 + progress);
            // Gray-zone harmonics: residuals 7..next are hard to salvage
            if post_residual >= 7 {
                score += gap.min(20.0) * 0.25 * (0.5 + progress);
            }
            // Fill-level vs dead-space trade: full bins can tolerate small dead residual
            let fill = bin_residual as f64 / cap;
            if fill > 0.75 {
                score -= (fill - 0.75) * 20.0;
            } else if fill < 0.5 {
                score += (0.5 - fill) * 16.0;
            }
            // Salvage floor: residual still usable by future items near mean scale
            let salvage_floor = (mean_residual * 0.5).min(nxt * 0.9);
            if pr >= salvage_floor {
                score -= 6.0 * (1.0 - progress);
            }
            // Stranded potential scaled by progress
            score += (gap / cap) * 30.0 * (0.4 + 0.6 * progress);
        }
    }

    // Last-chance bonus: few fitting bins -> strongly favor using this bin
    if fitting_bins_count <= 1 && bin_residual != bin_capacity {
        score -= 30.0;
    } else if fitting_bins_count <= 3 && bin_residual != bin_capacity {
        score -= (4.0 - fitting_bins_count as f64) * 5.5;
    } else {
        score += 0.1 * (fitting_bins_count as f64).ln();
    }

    // Density coupling: prefer bins tighter than mean residual
    let density_gap = (mean_residual - pr) / cap;
    score -= density_gap * (26.0 + 12.0 * progress);

    // Best-fit discrimination among fitting bins
    if fitting_bins_count > 1 && post_residual > 0 {
        let tight = 1.0 - norm_pr;
        score -= tight * 8.0 / fitting_bins_count as f64;
    }

    // Inter-item gap coupling: preserve flexible bins when few compete
    if next_item_size > 0 && fitting_bins_count <= 2 && post_residual >= next_item_size {
        let margin = (post_residual - next_item_size) as f64;
        score -= margin.min(30.0) * 0.35 * (1.0 - progress);
    }

    // Slight preference for tighter bins overall
    let tightness = 1.0 - (bin_residual as f64) / cap;
    score += 0.3 * tightness * (1.0 - progress);
    score -= (bin_residual as f64 / cap) * 5.0;

    // Perfect completion: bin becomes exactly full
    if post_residual == 0 && bin_residual != bin_capacity {
        score -= 17.0;
        if next_item_size > 0 && bin_residual % next_item_size == 0 {
            score -= 5.0;
        }
    }

    // Near-perfect fill bonus
    if post_residual > 0 && post_residual <= 6 && bin_residual != bin_capacity {
        if post_residual <= 3 {
            score -= 10.0 + (4 - post_residual) as f64 * 3.0;
        } else {
            score -= 12.0 - (post_residual - 3) as f64 * 2.0;
        }
    }

    // New-bin candidate logic: only open when justified
    if bin_residual == bin_capacity {
        if next_item_size > 0 && (item_size + next_item_size) == bin_capacity {
            score -= 46.0;
        } else if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score -= 10.0;
        } else {
            let none_fit_next = next_item_size > 0 && post_residual < next_item_size;
            let waste_factor = ((mean_residual / cap) - 0.1).max(0.0);
            let mut open_pen = 26.0 + 0.2 * open_bins_count as f64 + waste_factor * 22.0
                + 1.5 + 2.0 * (1.0 - progress);
            if none_fit_next {
                open_pen -= 14.0;
            }
            score += open_pen;
        }
        score += progress * 20.0;
        // New-bin restraint when a >=90% fill is available
        if next_item_size > 0 && post_residual > 0 && post_residual <= bin_capacity / 10 {
            score += 14.0;
        }
        if progress > 0.85 {
            score += (progress - 0.85) * 240.0;
        }
    }

    // Late-stream consolidation: penalize large residuals as stream progresses
    score += progress * progress * 14.0 * norm_pr;

    // Salvageability: residual reusable by wide range of items
    if post_residual > 0 && progress < 0.9 {
        let usable = (post_residual.min(100)) as f64 / 100.0;
        score -= usable * (1.0 - progress) * 6.0;
    }

    // Endgame tightening
    if progress > 0.7 && post_residual > 0 {
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 5.0 * progress;
        } else {
            score += 6.0 * norm_pr * progress;
        }
    }

    // Harmony bonus: item exactly halves the residual
    if bin_residual > item_size && (bin_residual - item_size) == item_size {
        score -= 9.0;
    }

    // Residual-vs-mean dead-space ratio
    if pr > mean_residual {
        score += (pr - mean_residual) * 0.18 * (0.5 + progress);
    }

    // Mid-stream salvage threshold: keep versatile bins open when several compete
    if next_item_size > 0 && post_residual >= next_item_size + 5 && fitting_bins_count > 2 && progress < 0.5 {
        score -= 3.5;
    }

    score
}

